def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds: total nanoseconds as an integer or a numeric type
    :param tz: optional tzinfo to attach to the resulting time
    :return: datetime.time object
    """
    try:
        total_ns = int(nanoseconds)
    except Exception as exc:
        raise ValueError(f"nanoseconds must be an integer: {exc}") from exc

    # Ensure nanoseconds are non-negative
    if total_ns < 0:
        raise ValueError("nanoseconds cannot be negative")

    # Convert nanoseconds to seconds and remaining nanoseconds
    seconds, remaining_ns = divmod(total_ns, 1_000_000_000)

    # Break seconds into hours, minutes, and seconds
    hours, rem = divmod(seconds, 3600)
    minutes, secs = divmod(rem, 60)

    if hours >= 24:
        raise ValueError("nanoseconds represent more than a full day")

    # Convert remaining nanoseconds to microseconds for datetime.time
    microseconds = remaining_ns // 1000  # 1 microsecond = 1_000 nanoseconds

    # Build and return the time object, optionally with tzinfo
    if tz is None:
        return datetime.time(hour=hours, minute=minutes, second=secs, microsecond=microseconds)
    else:
        return datetime.time(hour=hours, minute=minutes, second=secs,
                             microsecond=microseconds, tzinfo=tz)

