def unit_of_work(metadata=None, timeout=None):
    """This function is a decorator for transaction functions that allows extra control over how the transaction is carried out.

    For example, a timeout may be applied::

        from neo4j import unit_of_work

        @unit_of_work(timeout=100)
        def count_people_tx(tx):
            result = tx.run("MATCH (a:Person) RETURN count(a) AS persons")
            record = result.single()
            return record["persons"]

    :param metadata:
        a dictionary with metadata. Specified metadata will be attached to the executing transaction and visible in the output of ``dbms.listQueries`` and ``dbms.listTransactions`` procedures. It will also get logged to the ``query.log``. This functionality makes it easier to tag transactions and is equivalent to ``dbms.setTXMetaData`` procedure, see https://neo4j.com/docs/operations-manual/current/reference/procedures/ for procedure reference.

    :param timeout:
        the transaction timeout in seconds. Transactions that execute longer than the configured timeout will be terminated by the database. This functionality allows to limit query/transaction execution time. Specified timeout overrides the default timeout configured in the database using ``dbms.transaction.timeout`` setting. Value should not represent a negative duration. A zero duration will make the transaction execute indefinitely. None will use the default timeout configured in the database.

    """
    from functools import wraps
    from neo4j import TransactionConfig

    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            # The driver must be passed explicitly to the wrapper as a keyword argument.
            driver = kwargs.pop("driver", None)
            if driver is None:
                raise RuntimeError("Neo4j driver must be provided via keyword argument 'driver'")
            if timeout is not None:
                if timeout < 0:
                    raise ValueError("timeout must be non-negative or None")
                # Neo4j driver expects timeout in milliseconds as an int.
                timeout_ms = int(timeout * 1000) if timeout != 0 else None
            else:
                timeout_ms = None

            config_kwargs = {}
            if metadata:
                config_kwargs["metadata"] = metadata
            if timeout_ms is not None:
                config_kwargs["timeout"] = timeout_ms

            config = TransactionConfig(**config_kwargs) if config_kwargs else None

            session = driver.session()
            try:
                with session.begin_transaction(config=config) as tx:
                    try:
                        result = func(tx, *args, **kwargs)
                        tx.commit()
                        return result
                    except Exception:
                        tx.rollback()
                        raise
            finally:
                session.close

