    """
    Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # Ensure the record holds the expected attributes
    if not hasattr(self, "_data") or not hasattr(self, "_keys"):
        raise AttributeError("Record must have _data and _keys attributes")

    data_list = self._data
    keys_list = self._keys

    # Build a mapping from key name to index for quick lookup
    try:
        idx_from_key = {k: i for i, k in enumerate(keys_list)}
    except Exception:
        idx_from_key = {}

    # If no specific keys are requested, return everything
    if not keys:
        return {k: v for k, v in zip(keys_list, data_list)}

    result = {}
    for key in keys:
        # Integer indices
        if isinstance(key, int):
            if key < 0 or key >= len(data_list):
                raise IndexError(f"Index {key} out of bounds for record of length {len(data_list)}")
            kname = keys_list[key]
            result[kname] = data_list[key]
