def _reset_logging(cls):
    """
    Reset
    """
    try:
        root = logging.getLogger()
        # Remove all handlers attached to the root logger
        for handler in root.handlers[:]:
            root.removeHandler(handler)
            try:
                handler.close()
            except Exception:
                pass
        # Reconfigure root logger with default settings
        logging.basicConfig(
            level=logging.INFO,
            format='%(asctime)s - %(levelname)s - %(message)s'
        )
    except Exception:
        # If resetting fails, fall back to a minimal configuration
        try:
            logging.basicConfig(
                level=logging.WARNING,
                format='%(levelname)s: %(message)s'
            )
        except Exception:
            pass

def _reset_logging(cls):
    """
    Reset logging configuration to the default state.
    """
    import logging
    # Shut down the current logging system, which removes all handlers
    try:
        logging.shutdown()
    except Exception:
        # Ignore any exceptions during shutdown
        pass
    # Re‑initialize the root logger
    root = logging.getLogger()
    try:
        # Remove any remaining handlers (if shutdown didn't clear them)
        while root.handlers:
            handler = root.handlers[0]
            try:
                root.removeHandler(handler)
            except Exception:
                # If a handler fails to remove, ignore and continue
                pass
    except Exception:
        # If the handlers attribute is missing or not iterable, ignore
        pass
    # Reset the root logger level to WARNING (the default level)
    try:
        root.setLevel(logging.WARNING)
    except Exception:
        pass
    # Re‑apply the default basic configuration to provide a StreamHandler
    try:
        logging.basicConfig(level=logging.WARNING)
    except Exception:
        # In rare cases basicConfig might fail if logging is already configured;
        # if that happens we simply ignore
        pass

