                root_logger.removeHandler(handler)
                handler.close()
            except Exception:
                pass
        # Reconfigure root logger to default settings
        logging.basicConfig()
    except Exception as exc:
        try:
            logging.warning("Failed to reset logging: %s", exc)
        except Exception:
            pass

