def _legacy_mergeOrderings(orderings):
    """Merge multiple orderings so that within-ordering order is preserved

    Orderings are constrained in such a way that if an object appears
    in two or more orderings, then the suffix that begins with the
    object must be in both orderings.

    For example:

    >>> _legacy_mergeOrderings([
    ... ['x', 'y', 'z'],
    ... ['q', 'z'],
    ... [1, 3, 5],
    ... ['z']
    ... ])
    ['x', 'y', 'q', 1, 3, 5, 'z']

    """
    if not orderings:
        return []

    # Build graph
    successors = {}
    indegree = {}
    first_seen = {}
    index = 0

    for ordering in orderings:
        for i, node in enumerate(ordering):
            if node not in indegree:
                indegree[node] = 0
            if node not in successors:
                successors[node] = set()
            # record first appearance order for node
            if node not in first_seen:
                first_seen[node] = index
                index += 1
            if i < len(ordering) - 1:
                nxt = ordering[i + 1]
                if nxt not in successors[node]:
                    successors[node].add(nxt)
                    indegree[nxt] = indegree.get(nxt, 0) + 1
                    if nxt not in successors:
                        successors[nxt] = set()
                # ensure nxt in indegree dict
                if nxt not in indegree:
                    indegree[nxt] = 0

    # Kahn's algorithm with stable ordering based on first_seen
    # Start with nodes of indegree 0
    zero_indeg = [node for node, deg in indegree.items() if deg == 0]
    zero_indeg.sort(key=lambda x: first_seen.get(x, 0))
    result = []

    while zero_indeg:
        node = zero_indeg.pop(0)  # take earliest
        result.append(node)
        for succ in successors.get(node, []):
            indegree[succ] -= 1
            if indegree[succ] == 0:
                # insert succ maintaining order by first_seen
                pos = 0
                while pos < len(zero_indeg) and first_seen[zero_indeg[pos]] < first_seen[succ]:
                    pos += 1
                zero_indeg.insert(pos, succ)

    # If cycle exists (shouldn't per constraints), raise error
    if len(result) != len(indegree):
        raise ValueError("Orderings contain a cycle, cannot merge")

    return result

