    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not isinstance(classes, (list, tuple)):
        raise TypeError("classes must be a list or tuple of classes")
    res = []
    for c in classes:
        if not isinstance(c, type):
            raise TypeError(f"item {c!r} is not a class")
        # keep the class only if no other class in the list is a subclass of it
        if not any(issubclass(d, c) for d in classes if d is not c):
            res.append(c)
    return res

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not isinstance(classes, (list, tuple)):
        raise TypeError("classes must be a list or tuple of class objects")
    # remove duplicates while preserving order
    unique = []
    seen = set()
    for cls in classes:
        if not isinstance(cls, type):
            raise TypeError(f"all elements must be class objects, got {type(cls)}")
        if cls not in seen:
            unique.append(cls)
            seen.add(cls)
    # filter out classes that are ancestors of other classes in the list
    minimal = []
    for cls in unique:
        redundant = False
        for other in unique:
            if other is cls:
                continue
            try:
                if issubclass(other, cls):
                    redundant = True
                    break
            except TypeError:
                # ignore if objects are not suitable for issubclass
                continue
        if not redundant:
            minimal.append(cls)
    return minimal

