def _should_attempt_c_optimizations():
    """
    Return a true value if we should attempt to use the C optimizations.
    This takes into account whether we're on PyPy and the value of the
    ``PURE_PYTHON`` environment variable, as defined in `_use_c_impl`.
    """
    import os
    import sys

    # If the environment variable is set to a truthy value, do not use C.
    pure_python = os.getenv("PURE_PYTHON")
    if pure_python is not None:
        # Treat common truthy strings as indicating pure Python mode.
        if pure_python.lower() in ("1", "true", "yes", "on"):
            return False

    # Determine if running under PyPy (which typically does not support C extensions).
    try:
        # Python 3.4+ offers sys.implementation
        if getattr(sys, "implementation", None) and sys.implementation.name.lower() == "pypy":
            return False
    except Exception:
        # Fallback to platform detection for older versions.
        try:
            import platform
            if platform.python_implementation().lower() == "pypy":
                return False
        except Exception:
            # In case detection fails, assume safe to attempt C optimizations.
            pass

    # Default: attempt C optimizations.
    return True

def _c_optimizations_ignored():
    """The opposite of `_c_optimizations_required`."""
    pass

def _c_optimizations_required():
    """
    Return a true value if the C optimizations are required.

    This uses the ``PURE_PYTHON`` variable as documented in `_use_c_impl`.
    """
    try:
        # If PURE_PYTHON is True, we are running pure Python and no C extensions are required.
        # If it is False or any other falsy value, we need the C optimisations.
        return not bool(PURE_PYTHON)
    except NameError:
        # If PURE_PYTHON is not defined, assume C optimisations are required.
        return True

