def to_csv(self, separator=",", header=None):
        """Convert graph's points to CSV.

        *separator* delimits values, the default is comma.

        *header*, if not ``None``, is the first string of the output
        (new line is added automatically).

        Since a graph can be multidimensional,
        for each point first its coordinate is converted to string
        (separated by *separator*), then each part of its value.
        """
        lines = []

        # Add header if provided
        if header is not None:
            if isinstance(header, (list, tuple)):
                lines.append(separator.join(str(item) for item in header))
            else:
                lines.append(str(header))

        try:
            iterator = iter(self)
        except Exception as exc:
            raise TypeError(f"{self.__class__.__name__} object is not iterable") from exc

        for point in iterator:
            # Each point is expected to be a tuple (coord, value)
            try:
                coord, value = point
            except Exception:
                # Treat entire point as coordinate and no value
                coord, value = point, None

            # Convert coordinate to string
            if isinstance(coord, (list, tuple)):
                coord_str = separator.join(str(v) for v in coord)
            else:
                coord_str = str(coord)

            # Convert value(s) to string(s)
            if value is None:
                row_parts = [coord_str]
            else:
                if isinstance(value, (list, tuple)):
                    value_strs = [str(v) for v in value]
                else:
                    value_strs = [str(value)]
                row_parts = [coord_str] + value_strs

            lines.append(separator.join(row_parts))

        return "\n".join(lines) + ("\n" if lines else "")

