          Iterables are converted to tables.

    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.

    To convert :class:`Graph` to CSV inside a Lena sequence,
    use :class:`lena.output.ToCSV`.
    """
    # Basic validation of separator
    if not isinstance(separator, str) or len(separator) != 1 or separator == "\\":
        raise ValueError("separator must be a single non‑backslash character")

    lines = []

    # Add header if provided
    if header is not None:
        lines.append(str(header))

    # Attempt to iterate over graph points
    try:
        for point in self:
            # Try to unpack a point into coordinate and value
            try:
                coord, val = point
            except Exception:
                # If unpacking fails, treat the whole point as the coordinate
                coord, val = point, None

            # Convert coordinate to string
            if hasattr(coord, "__iter__") and not isinstance(coord, (str, bytes)):
                coord_str = separator.join(str(v) for v in coord)
            else:
                coord_str = str(coord)

            # Convert value to string
            if val is None:
                val_str = ""
            elif hasattr(val, "__iter__") and not isinstance(val, (str, bytes)):
                val_str = separator.join(str(v) for v in val)
            else:
                val_str = str(val)

            lines.append(coord_str + separator + val_str)
    except Exception as exc:
        raise RuntimeError("An error occurred while converting graph to CSV") from exc

    # Return a single string containing all lines
    return "\n".join(lines)

