        raise KeyError(f"Coordinate {coord_name!r} not found in the object")

    # Attempt to retrieve error indices directly from the coordinate variable
    if hasattr(coord_var, "err_indices"):
        return coord_var.err_indices
    if hasattr(coord_var, "errors") and hasattr(coord_var.errors, "indices"):
        return coord_var.errors.indices

    # Fallback to an object-level dictionary that may hold error indices
    if hasattr(self, "err_indices") and isinstance(self.err_indices, dict):
        err_idx = self.err_indices.get(coord_name)
        if err_idx is not None:
            return err_idx

    # If no error indices could be found, raise an informative exception
    raise AttributeError(
        f"No error indices available for coordinate {coord_name!r}"
    )

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Convert inputs to numpy arrays for vectorised operations
    bins_arr = np.asarray(bins)
    # Handle the edges input: can be a single array or a sequence for 2‑D histograms
    if isinstance(edges, (list, tuple)):
        # 1‑D case (len(edges) == 1) or 2‑D case (len(edges) == 2)
        if len(edges) == 1:
            e = np.asarray(edges[0])
            widths = np.diff(e)
            if bins_arr.shape != widths.shape:
                raise ValueError("Shape of bins does not match edge widths.")
            return np.sum(bins_arr * widths)
        elif len(edges) == 2:
            e0 = np.asarray(edges[0])
            e1 = np.asarray(edges[1])
            w0 = np.diff(e0)
            w1 = np.diff(e1)
            if bins_arr.shape != (len(w0), len(w1)):
                raise ValueError("Shape of bins does not match 2‑D edge widths.")
            # Compute outer product of widths to get bin areas
            areas = np.outer(w0, w1)
            return np.sum(bins_arr * areas)
        else:
            raise ValueError("Edges must be a sequence of 1 or 2 arrays for 1‑D or 2‑D histograms.")
    else:
        # Assume 1‑D edges provided directly
        e = np.asarray(edges)
        widths = np.diff(e)
        if bins_arr.shape != widths.shape:
            raise ValueError("Shape of bins does not match edge widths.")
        return np.sum(bins_arr * widths)

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Convert inputs to numpy arrays
    try:
        bins_arr = np.asarray(bins, dtype=float)
        edges_arr = np.asarray(edges, dtype=float)
    except Exception as exc:
        raise ValueError("bins and edges must be array-like") from exc

    # Basic dimensionality checks
    if edges_arr.ndim != 1:
        raise ValueError("edges must be a 1‑D array")
    if bins_arr.ndim != 1:
        raise ValueError("bins must be a 1‑D array")

    # Length consistency check
    if edges_arr.size != bins_arr.size + 1:
        raise ValueError("edges length must be equal to bins length + 1")

    # Monotonicity check of edges
    if not np.all(np.diff(edges_arr) > 0):
        raise ValueError("edges must be strictly increasing")

    # Compute widths and integrate
    widths = np.diff(edges_arr)
    return float(np.sum(bins_arr * widths))

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration. Their format is defined in :class:`.histogram` description.
    """
    # Convert bins to a numpy array
    try:
        import numpy as np
    except Exception:
        raise ImportError("numpy is required for integral()")
    bins_arr = np.asarray(bins, dtype=float)

    # Case 1: 1‑D histogram
    if np.ndim(edges) == 1:
        widths = np.diff(np.asarray(edges, dtype=float))
        return np.sum(bins_arr * widths)

    # Case 2: Multi‑dimensional histogram (edges is a sequence of 1‑D arrays)
    # Compute widths for each dimension
    widths = [np.diff(np.asarray(e, dtype=float)) for e in edges]

    # Build a broadcast‑compatible volume array using np.ix_
    mesh = np.ix_(*widths)
    volume = mesh[0]
    for m in mesh[1:]:
        volume = volume * m

    # Ensure the volume array has the same shape as bins
    if volume.shape != bins_arr.shape:
        raise ValueError(
            "Bin edge widths could not be broadcast to match bin array shape."
        )

    return np.sum(bins_arr * volume)

