def difference(d1, d2, level=-1):
    """
    Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise TypeError("difference requires both arguments to be dictionaries")

    def _subdif(d1sub, d2sub, lvl):
        res = {}
        for k, v1 in d1sub.items():
            if k not in d2sub:
                # key absent in d2 → copy value
                res[k] = v1 if not isinstance(v1, dict) else v1
                continue

            v2 = d2sub[k]
            if isinstance(v1, dict) and isinstance(v2, dict):
                # recursion allowed?
                if lvl == -1 or lvl > 1:
                    sub = _subdif(v1, v2, lvl - 1 if lvl != -1 else -1)
                    if sub:
                        res[k] = sub
                else:
                    # level 1: treat as difference, copy entire subdict
                    res[k] = v1
            else:
                # non-dict values: include if they differ
                if v1 != v2:
                    res[k] = v1
        return res

    return _subdif(d1, d2, level)

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    def _diff(d1_sub, d2_sub, lvl):
        if not isinstance(d1_sub, dict) or not isinstance(d2_sub, dict):
            # If either is not a dict, no recursive comparison needed.
            return None

        diff = {}
        for key, val in d1_sub.items():
            if key not in d2_sub:
                # The whole subdictionary (or value) is kept as is.
                diff[key] = val
                continue

            val2 = d2_sub[key]
            # Determine if we need to recurse into nested dicts.
            if isinstance(val, dict) and isinstance(val2, dict) and (lvl == -1 or lvl > 0):
                next_lvl = -1 if lvl == -1 else lvl - 1
                subdiff = _diff(val, val2, next_lvl)
                if subdiff is not None:
                    diff[key] = subdiff
            elif val != val2:
                diff[key] = val

        return diff if diff else None

    if not isinstance(d1, dict) or not isinstance(d2, dict):
        return {}

    result = _diff(d1, d2, level)
    return result if result is not None else {}

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    # Ensure coordinate is array-like
    coord = np.asarray(coord)
    # Validate existence of edges and histogram data
    if not hasattr(self, 'edges'):
        raise AttributeError("Histogram object must have an 'edges' attribute.")
    if not hasattr(self, 'hist'):
        raise AttributeError("Histogram object must have a 'hist' attribute.")

    # Convert edges to a list (support single or multiple dimensions)
    if isinstance(self.edges, np.ndarray):
        # Assume 1D edges stored as a 1D array
        edges_list = [self.edges]
    else:
        edges_list = list(self.edges)

    ndim = len(edges_list)

    # If coord is scalar and histogram is 1D, wrap it
    if ndim == 1 and coord.ndim == 0:
        coord = coord.reshape(1)

    if coord.shape[-1] != ndim:
        raise ValueError(f"Coordinate dimensionality {coord.shape[-1]} does not match histogram dimensions {ndim}.")

    # Find bin indices for each dimension
    bin_indices = []
    for dim, x in enumerate(coord.T):
        edges = edges_list[dim]
        # Find the right bin using searchsorted; get index of left edge
        bin_idx = np.searchsorted(edges, x, side='right') - 1
        # Check bounds: ignore if out of range
        if np.any(bin_idx < 0) or np.any(bin_idx >= len(edges) - 1):
            return  # Coordinates outside histogram edges are ignored
        bin_indices.append(bin_idx)

    # Reduce list of arrays to a tuple index
    idx = tuple(b.flatten() for b in bin_indices)

    # Accumulate weight
    try:
        self.hist[idx] += weight
    except Exception:
        # Fallback for hist stored in a dictionary
        if isinstance(self.hist, dict):
            for key in idx:
                self.hist[key] = self.hist.get(key, 0) + weight
        else:
            raise ValueError("Unsupported histogram storage format.")
    return self

def fill(self, coord, weight=1):
    """
    Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    # Ensure numpy is available
    import numpy as np

    # Convert coordinates to ndarray
    try:
        coord_arr = np.asarray(coord, dtype=float)
    except Exception as exc:
        raise ValueError(f"Coord must be array-like, got {coord!r}") from exc

    # Dimensions consistency check
    if coord_arr.ndim != 1:
        raise ValueError("coord must be a 1‑D sequence of length equal to the number "
                         f"of histogram dimensions ({len(self.edges)}), got {coord_arr.ndim}‑D")
    if coord_arr.size != len(self.edges):
        raise ValueError(f"coord size ({coord_arr.size}) does not match histogram "
                         f"dimension ({len(self.edges)})")

    # Verify weight is scalar numeric
    if np.isscalar(weight):
        try:
            weight_val = float(weight)
        except Exception as exc:
            raise ValueError(f"weight must be a numeric scalar, got {weight!r}") from exc
    else:
        try:
            weight_val = float(np.asarray(weight))
        except Exception as exc:
            raise ValueError(f"weight must be a numeric scalar, got {weight!r}") from exc

    # Determine bin indices for each dimension
    bin_indices = []
    for dim, val in enumerate(coord_arr):
        edges = np.asarray(self.edges[dim], dtype=float)
        # Reject if value outside the bin range
        if val < edges[0] or val >= edges[-1]:
            # Outside histogram edges: ignore
            return
        # Locate bin index using searchsorted
        idx = np.searchsorted(edges, val, side='right') - 1
        if idx < 0 or idx >= len(edges) - 1:
            # Outside the effective bin range; ignore
            return
        bin_indices.append(idx)

    # Update the histogram bin
    try:
        self.hist[tuple(bin_indices)] += weight_val
    except Exception as exc:
        raise RuntimeError(f"Failed to update histogram bin {bin_indices!r} with weight {weight_val!r}") from exc

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    import re
    from django.core.exceptions import ValidationError

    # Regular expressions that labels must match.
    # These are the same patterns used elsewhere in the project.
    LABEL_KEY_RE = re.compile(r'^[a-zA-Z0-9_]+$')
    LABEL_VALUE_RE = re.compile(r'^[a-zA-Z0-9_]+$')

    errors = []

    for key, value in labels.items():
        # Validate key type.
        if not isinstance(key, (str, bytes)):
            errors.append({str(key): 'expected string or bytes-like object'})
        else:
            # Validate key regex.
            if not LABEL_KEY_RE.match(key):
                errors.append(
                    {key: f"Label key '{key}' does not match the regex "
                          f"{LABEL_KEY_RE.pattern}"}
                )

        # Validate value type.
        if not isinstance(value, (str, bytes)):
            errors.append({str(value): 'expected string or bytes-like object'})
        else:
            # Validate value regex.
            if not LABEL_VALUE_RE.match(value):
                errors.append(
                    {value: f"Label value '{value}' does not match the regex "
                          f"{LABEL_VALUE_RE.pattern}"}
                )

    if errors:
        raise ValidationError(errors)

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    errors = []

    # Patterns for key and value validation – adjust these as required.
    key_pattern = re.compile(r'^[A-Za-z_][A-Za-z0-9_]*$')
    value_pattern = re.compile(r'^[A-Za-z0-9_]+$')

    for key, value in labels.items():
        # Key validation
        if not isinstance(key, (str, bytes)):
            errors.append({str(key): 'expected string or bytes-like object'})
        else:
            if not key_pattern.match(key):
                errors.append(
