                    {value: f"Label value '{value}' does not match the regex {value_pattern.pattern}"}
                )

    if errors:
        raise ValidationError(errors)

def _get_resource_name_regex():
    """Build or return the regular expressions that are used to validate
    the name of the Krake resources.

    Returns:
        (re.Pattern): the compiled regular expressions, to validate
        the resource name.
    """
    try:
        # Kubernetes style DNS subdomain name: lowercase alphanumerics,
        # separated by hyphens, must start and end with an alphanumeric.
        pattern = r'^[a-z0-9]([-a-z0-9]*[a-z0-9])?$'
        return re.compile(pattern)
    except re.error:
        # Fallback to a very permissive pattern if compilation fails
        return re.compile(r'^.+$')

def validate_value(value):
    """
    Validate the given value against the corresponding regular expression.

    Args:
        value: the string to validate

    Raises:
        ValidationError: if the given value is not conform to the regular expression.
    """
    if not isinstance(value, (str, bytes)):
        raise ValidationError("value must be a string or bytes")
    if isinstance(value, bytes):
        try:
            value = value.decode("utf-8")
        except UnicodeDecodeError as exc:
            raise ValidationError(f"cannot decode bytes: {exc}") from exc
    # Define the regular expression that the value should match.
    # This can be adjusted to the specific requirement.
    pattern = r"^[A-Za-z0-9_]+$"
    try:
        if not re.match(pattern, value):
            raise ValidationError(f"'{value}' does not match pattern {pattern}")
    except re.error as exc:
        raise ValidationError(f"Invalid regex pattern: {exc}") from exc

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """Generate a default observer schema dictionary from a Kubernetes manifest fragment.

    The function recursively walks ``manifest_dict`` and creates a new dictionary
    where all terminal values that are not lists or dicts are replaced by None.
    When ``first_level`` is True the top level is treated as a complete
    observer_schema: only a predefined set of keys are copied from the source
    manifest; every other scalar value is set to None.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary
            represents the whole observer schema of a Kubernetes resource.

    Returns:
        dict: Generated partial observer_schema
    """
    if not isinstance(manifest_dict, dict):
        raise ValueError("manifest_dict must be a dict, got %s" % type(manifest_dict).__name__)

    # Identifying fields that should be preserved in the top‑level dictionary
    IDENTIFYING_KEYS = {"name", "namespace", "uid", "kind", "apiVersion"}

    output = {}
    for key, value in manifest_dict.items():
        if isinstance(value, dict):
            # Recurse – deeper levels never have 'first_level' semantics
            output[key] = generate_default_observer_schema_dict(value, first_level=False)
        elif isinstance(value, list):
            # Preserve the list structure; its elements are processed recursively
            new_list = []
            for item in value:
                if isinstance(item, dict):
                    new_list.append(generate_default_observer_schema_dict(item, first_level=False))
                else:
                    new_list.append(None)
            output[key] = new_list
        else:
            # Scalar value: keep only identifying fields when on the outermost level
            if first_level and key in IDENTIFYING_KEYS:
                output[key] = value
            else:
                output[key] = None
    return output

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Recursively creates a new dictionary from ``manifest_dict``.
    All non-dict and non-list values are replaced with ``None``.
    When ``first_level`` is True, values of identifying fields
    ('apiVersion' and 'kind') are preserved from the original
    ``manifest_dict``.
    """
    if not isinstance(manifest_dict, dict):
        raise ValueError("manifest_dict must be a dict")

    result = {}
    identifying_fields = {"apiVersion", "kind"}

    for key, value in manifest_dict.items():
        if isinstance(value, dict):
            # Recurse into nested dictionaries; do not treat them as identifying
            result[key] = generate_default_observer_schema_dict(value, first_level=False)
        elif isinstance(value, list):
            # For lists, process each element. If an element is a dict, recurse;
            # otherwise use None.
            processed = []
            for item in value:
                if isinstance(item, dict):
                    processed.append(generate_default_observer_schema_dict(item, first_level=False))
                else:
                    processed.append(None)
            result[key] = processed
        else:
            # Primitive types: keep the original value only if it's an identifying
            # field at the top level; otherwise replace with None.
            if first_level and key in identifying_fields:
                result[key] = value
            else:
                result[key] = None

    return result

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:`update_last_applied_manifest_list_from_resp`, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being
            updated
        observer_schema (dict): partial ``observer_schema``
        response (dict): partial response from the Kubernetes API.

    Raises:
        KeyError: If the observed field is not present in the Kubernetes response
    """
    if not isinstance(observer_schema, dict):
        raise TypeError("observer_schema must be a dict")

    for key, sub_schema in observer_schema.items():
        # Ensure the field exists in the Kubernetes response
        if key not in response:
            raise KeyError(f"Observed field '{key}' missing in response")

        # If the schema indicates a nested mapping, recurse
        if isinstance(sub_schema, dict):
            # Initialize nested dict in last_applied_manifest if missing
            if key not in last_applied_manifest:
                last_applied_manifest[key] = {}
            elif not isinstance(last_applied_manifest[key], dict):
                # If an existing value is not a dict, overwrite it
                last_applied_manifest[key] = {}
            sub_response = response[key]
            if not isinstance(sub_response, dict):
                raise KeyError(
                    f"Expected dict for field '{key}' in response, "
                    f"but got {type(sub_response).__name__}"
                )
            update_last_applied_manifest_dict_from_resp(
                last_applied_manifest[key], sub_schema, sub_response
            )
        else:
            # Primitive field: set if not already present
            if key not in last_applied_manifest:
                last_applied_manifest[key] = response[key]

    return last_applied_manifest

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Ensure application has a spec attribute
    if not hasattr(app, "spec"):
        return

    # Retrieve the manifest (list or dict of Kubernetes resources)
    manifest = getattr(app.spec, "manifest", None)
    if manifest is None:
        return

    # Ensure there is a dictionary to store observer schemas
    observer_schema = getattr(app.spec, "observer_schema", None)
    if observer_schema is None:
        observer_schema = {}
        setattr(app.spec, "observer_schema", observer_schema)

    # Helper function to generate a simple default schema
    def _default_schema():
        # A minimal placeholder schema: allow any object
        return {"type": "object"}

    # Iterate over the resources in the manifest
    if isinstance(manifest, dict):
        # Assume key is a resource name or identifier
        items = manifest.items()
    elif isinstance(manifest, list):
        # List of resource dicts
        items = enumerate(manifest)
    else:
        # Unsupported type
        return

    for key, resource in items:
        # Attempt to extract a unique name for the resource
        res_name = None
        if isinstance(resource, dict):
            res_name = resource.get("metadata", {}).get("name")
        if not res_name:
            # Fallback to the key/index if no metadata name
            res_name = key
        if not res_name:
            continue

        # Skip if a custom schema already exists
        if res_name in observer_schema:
            continue

        # Assign the default schema
        observer_schema[res_name] = _default_schema()

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema

    Returns:
        dict: Mapping of resource kind to its default observer schema.
    """
    # Basic validation of the input object
    if app is None:
        raise ValueError("`app` cannot be None.")
    if not hasattr(app, "spec"):
        raise AttributeError("The provided app object does not have a 'spec' attribute.")
    if not hasattr(app.spec, "manifest"):
        # If there is no manifest we simply return an empty schema mapping
        return {}

    default_schemas = {}
    try:
        # Ensure we are working with an iterable collection of resources
        resources = list(app.spec.manifest)
    except Exception as exc:
        raise TypeError("app.spec.manifest must be an iterable of Kubernetes resources.") from exc

    for resource in resources:
        # Each resource is expected to be a mapping with at least a 'kind' key
        kind = resource.get("kind") if isinstance(resource, dict) else None
        if not kind:
            # Skip any malformed entries
            continue

        # Skip explicit schemas already present in the app's observer section (if any)
        observer_section = getattr(app.spec, "observers", {})
        if isinstance(observer_section, dict) and kind in observer_section:
            continue

        # Construct a minimal default schema for this kind
        # Here we simply create an empty object schema as a placeholder.
        # Users may later refine this schema as needed.
        default_schema = {
            "type": "object",
            "x-krake-kind": kind,
            "properties": {}
        }
        default_schemas[kind] = default_schema

    return default_schemas

def generate_default_observer_schema(app):
    """
    Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Retrieve the application's spec; raise if missing
    spec = getattr(app, "spec", None)
    if spec is None:
        raise AttributeError("The application does not have a 'spec' attribute")

    # Get the list of resources from the manifest; it may be a list or iterable
    manifest = getattr(spec, "manifest", [])
    if not isinstance(manifest, list):
        try:
            manifest = list(manifest)
        except TypeError:
            # If it's not iterable, treat as empty manifest
            manifest = []

    # Determine the set of kinds for which a custom observer schema is already defined
    # We try a few possible attribute names that might hold these definitions.
    custom_schemas = getattr(spec, "custom_observer_schemas", None)
    if custom_schemas is None:
        custom_schemas = getattr(spec, "observer_schemas", None)
    if custom_schemas is None or not isinstance(custom_schemas, dict):
        custom_schemas = {}

    # Prepare the resulting default schemas mapping
    default_schemas = {}

    for resource in manifest:
        kind = resource.get("kind") if isinstance(resource, dict) else None
        if not kind:
            continue  # Skip resources without a kind

        # Skip kinds that already have a custom observer schema
        if kind in custom_schemas:
            continue

        # Generate a minimal default observer schema capturing the most common
        # fields that users are likely to want.  This includes metadata such
        # as name, namespace, labels, and annotations.
        default_schemas[kind] = {
            "type": "object",
            "properties": {
                "metadata": {
                    "type": "object",
                    "properties": {
                        "name": {"type": "string"},
                        "namespace": {"type": "string"},
                        "labels": {"type": "object"},
                        "annotations": {"type": "object"},
                    },
                    "required": ["name"],
                }
            },
        }

    # Attach the generated schemas back to the spec if an attribute exists, otherwise
    # create a new one.  Returning the mapping allows callers to inspect it if needed.
    if hasattr(spec, "observer_schemas"):
        spec.observer_schemas.update(default_schemas)
    else:
        setattr(spec, "observer_schemas", default_schemas)

    return default_schemas

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    try:
        spec = getattr(app, "spec", None)
        if spec is None:
            return
        manifest = getattr(spec, "manifest", {})
        if not isinstance(manifest, dict):
            return

        # Ensure the observer_schema dict exists on the spec
        observer_schema = getattr(spec, "observer_schema", None)
        if observer_schema is None:
            observer_schema = {}
            setattr(spec, "observer_schema", observer_schema)

        for resource_key, resource_value in manifest.items():
            # Skip if a custom observer schema already exists
            if resource_key in observer_schema:
                continue

            # Handle single dict or list of dicts
            resources = (
                resource_value
                if isinstance(resource_value, list)
                else [resource_value]
            )
            for idx, res in enumerate(resources):
                if not isinstance(res, dict):
                    continue

                kind = res.get("kind", "Unknown")
                api_version = res.get("apiVersion", "v1")
                # Use the name in the metadata if available, otherwise derive one
                metadata = res.get("metadata", {})
                name = metadata.get("name", f"{resource_key}-{idx}")
                schema_name = (
                    f"{resource_key}-{idx}"
                    if isinstance(resource_value, list)
                    else resource_key
                )
                observer_schema[schema_name] = {
                    "apiVersion": api_version,
                    "kind": kind,
                    "metadata": {"name": name},
                }

    except Exception:
        # Silently ignore errors to avoid breaking the deployment flow
        pass

def formatmany(
    self,
    sql: AnyStr,
    many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]],
) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    """
    Convert the SQL query to use the out-style parameters instead of the
    in-style parameters.

    *sql* (str or bytes) is the SQL query.

    *many_params* is an iterable containing each set of in-style parameters (params).

    Returns a tuple containing:
        - The formatted SQL query.
        - A list containing each set of converted out-style parameters.
    """
    import re
    from collections.abc import Mapping, Sequence, Iterable

    # Resolve in_style (default to 'named' if not set)
    in_style = getattr(getattr(self, "SQLParams", None), "in_style", None) or "named"

    # Convert sql to string for manipulation
    if isinstance(sql, bytes):
        sql_str = sql.decode("utf-8")
    else:
        sql_str = sql

    out_params_list: List[Any] = []

    if in_style == "qmark":
        # Already using question marks; no transformation needed
        formatted_sql = sql_str
        for params in many_params:
            if isinstance(params, Sequence) and not isinstance(params, (str, bytes)):
                out_params_list.append(tuple(params))
            elif isinstance(params, Mapping):
                out_params_list.append(tuple(params.values()))
            else:
                raise TypeError(
                    f"Each param set must be a sequence or mapping; got {type(params)}"
                )

    elif in_style == "named":
        # Replace named placeholders with ?
        # Supports :name and :1 styles
        named_pat = re.compile(r"(:[a-zA-Z_][a-zA-Z0-9_]*)")
        names = [m.group(1)[1:] for m in named_pat.finditer(sql_str)]

        if not names:
            # if no named placeholders, just fallback to positional
            formatted_sql = sql_str
        else:
            formatted_sql = re.sub(r":\w+", "?", sql_str)

        for params in many_params:
            if not isinstance(params, Mapping):
                raise TypeError(
                    f"For named paramstyle, each param set must be a mapping; got {type(params)}"
                )
            try:
                out_params_list.append(tuple(params[name] for name in names))
            except KeyError as exc:
                raise KeyError(
                    f"Missing key {exc.args[0]} in params mapping for query {sql_str}"
                ) from exc

    elif in_style == "numeric":
        # Replace numeric placeholders :1, :2, ... with ?
        numeric_pat = re.compile(r":(\d+)")
        indices = [int(m.group(1)) for m in numeric_pat.finditer(sql_str)]

        if not indices:
            formatted_sql = sql_str
        else:
            formatted_sql = re.sub(r":\d+", "?", sql_str)

        # We expect a mapping where keys are integers
        for params in many_params:
            if not isinstance(params, Mapping):
                raise TypeError(
                    f"For numeric paramstyle, each param set must be a mapping; got {type(params)}"
                )
            try:
                out_params_list.append(tuple(params[i] for i in indices))
            except KeyError as exc:
                raise KeyError(
                    f"Missing numeric key {exc.args[0]} in params mapping for query {sql_str}"
                ) from exc

    elif in_style == "format":
        # Placeholder %s or %(<name>)s
        # Replace %s with ? for positional; retain mapping order for dict
        formatted_sql = re.sub(r"%s|%\(\w+\)s", "?", sql_str)

        for params in many_params:
            if isinstance(params, Mapping):
                out_params_list.append(tuple(params.values()))
            elif isinstance(params, Sequence) and not isinstance(params, (str, bytes)):
                out_params_list.append(tuple(params))
            else:
                raise TypeError(
                    f"Each param set must be a sequence or mapping; got {type(params)}"
                )

    else:
        #

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        result = self._validate(path)
        if hasattr(result, 'errors') and result.errors:
            return False
        if isinstance(result, (list, tuple)):
            return not result
        return True
    except Exception:
        return False

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    # Do a quick check for an empty or falsy path
    if not path:
        return False

    # Try to resolve a pyfs root, if the passed object is a pyfs root
    try:
        # Some pyfs objects expose a `root` attribute or `as_root_path` method
        if hasattr(path, "root"):
            path = path.root
        elif hasattr(path, "as_root_path"):
            path = path.as_root_path()
    except Exception:
        # If any error occurs, just keep the original path
        pass

    # Attempt to use the OCFL validation routine if available
    try:
        from ocfl import validate as ocfl_validate  # type: ignore
    except Exception:
        # If the ocfl module or validate function is not available, we cannot validate
        return False

    try:
        # The validate function is expected to return a boolean or a tuple
        # (is_valid, warnings) where warnings are optional.
        result = ocfl_validate(path)
        if isinstance(result, tuple):
            is_valid, _warnings = result
        else:
            is_valid = result
        return bool(is_valid)
    except Exception:
        # Any exception raised during validation indicates an invalid object
        return False

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    if not path:
        return False
    try:
        # Accept string or path-like objects
        p = os.fspath(path)
    except Exception:
        return False

    p = os.path.abspath(p)
    if not os.path.isdir(p):
        return False

    # Check for required OCFL files
    required_files = ['.ocfl_version', '.ocfl_manifest', '.ocfl_index']
    for fname in required_files:
        fpath = os.path.join(p, fname)
        if not os.path.isfile(fpath):
            return False

    # Validate that the .ocfl_version file contains a non-empty string
    try:
        with open(os.path.join(p, '.ocfl_version'), 'r', encoding='utf-8') as f:
            version = f.read().strip()
        if not version:
            return False
    except Exception:
        return False

    return True

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        if not path:
            return False
        # Ensure the path points to an existing directory
        if not os.path.isdir(path):
            return False
        # A minimal OCFL object should contain an objects directory,
        # a manifest directory, and an info file (or equivalent).
        required_dirs = ['objects', 'manifest']
        for d in required_dirs:
            if not os.path.isdir(os.path.join(path, d)):
                return False
        if not os.path.isfile(os.path.join(path, 'info')):
            # Some implementations use 'ocfl-info' or similar; this check can be extended.
            return False
    except Exception:
        return False
    return True

