def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # Basic type check
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary")

    # Determine effective specification version
    spec_version = self.spec_version
    if extract_spec_version:
        type_value = inventory.get("type")
        if isinstance(type_value, str) and type_value in getattr(self, "allowed_spec_versions", []):
            spec_version = type_value
        else:
            # If type value is missing or invalid, fall back to the object's spec_version
            pass

    # Perform validation according to the selected specification version
    try:
        validation_fn = getattr(self, f"_validate_{spec_version}", None)
    except Exception:
        validation_fn = None

    if validation_fn and callable(validation_fn):
        validation_fn(inventory)
    else:
        # If no specific validator exists, perform a generic check
        required_keys = getattr(self, "required_keys", {}).get(spec_version, [])
        missing_keys = [k for k in required_keys if k not in inventory]
        if missing_keys:
            raise ValueError(
                f"Missing required keys for spec version '{spec_version}': {missing_keys}"
            )

    # If all checks pass, return the (possibly normalised) inventory
    return inventory

def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # Basic existence and type checks
    if inventory is None:
        raise ArgumentError("inventory", "Inventory cannot be None")
    if not isinstance(inventory, dict):
        raise ArgumentError(
            "inventory",
            f"Inventory must be a dict, got {type(inventory).__name__}"
        )

    # Determine specification version
    spec_version = getattr(self, "spec_version", None)
    if extract_spec_version:
        type_val = inventory.get("type")
        if type_val is not None:
            if not isinstance(type_val, str):
                raise ArgumentError(
                    "type", f"Spec version must be a string, got {type(type_val).__name__}"
                )
            # Check against a known set if available
            allowed_versions = getattr(self, "allowed_spec_versions", None)
            if allowed_versions is not None and type_val not in allowed_versions:
                raise ArgumentError(
                    "type",
                    f'Unsupported spec version "{type_val}", expected one of {allowed_versions}'
                )
            # If it is recognised, use it
            spec_version = type_val

    if spec_version is None:
        raise ArgumentError(
            "spec_version",
            "Cannot determine specification version; provide it or set self.spec_version"
        )

    # Optional: Validate required fields based on spec_version
    required_fields_map = getattr(self, "required_fields", {})
    required_fields = required_fields_map.get(spec_version, [])
    missing_fields = [f for f in required_fields if f not in inventory]
    if missing_fields:
        raise ArgumentError(
            "inventory",
            f"Missing required fields for spec version {spec_version}: {missing_fields}"
        )

    # Example package list validation (if inventory contains 'packages')
    if "packages" in inventory:
        packages = inventory["packages"]
        if not isinstance(packages, list):
            raise ArgumentError(
                "packages",
                f"Expected list of packages, got {type(packages).__name__}"
            )
        for idx, pkg in enumerate(packages):
            if not isinstance(pkg, dict):
                raise ArgumentError(
                    f"packages[{idx}]",
                    f"Package entry must be a dict, got {type(pkg).__name__}"
                )
            # Common fields within a package
            if "name" not in pkg or "version" not in pkg:
                raise ArgumentError(
                    f"packages[{idx}]",
                    'Each package must contain "name" and "version" fields'
                )

    # If all checks passed, consider the inventory valid
    return True

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    errors = []

    # Verify that each file in the manifest has a known digest
    for file in manifest_files:
        digests = self.analyzed_files.get(file)
        if not digests:
            errors.append(f"Manifest file '{file}' not found in analyzed files.")
            continue
        # Use the first digest as the expected one (assuming one digest per file)
        digest = digests[0]
        if digest not in digests_used:
            errors.append(f"Digest '{digest}' for file '{file}' is not marked as used.")

    # Verify that every used digest exists among the analyzed files
    known_digests = { d for digs in self.analyzed_files.values() for d in digs }
    for digest in digests_used:
        if digest not in known_digests:
            errors.append(f"Used digest '{digest}' not found among analyzed files.")

    if errors:
        raise ValueError("\n".join(errors))

    return True

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Ensure inputs are iterable
    if manifest_files is None:
        manifest_files = []
    if digests_used is None:
        digests_used = []

    needed = set()
    # Extract digests from the manifest files
    for mf in manifest_files:
        try:
            # Accept either a path (str) or a file-like object
            if isinstance(mf, str):
                with open(mf, "r", encoding="utf-8") as fh:
                    content = fh.read()
            else:
                # Assume file-like
                content = mf.read()
            for line in content.splitlines():
                # A very tolerant approach: collect any token that looks like a hex digest
                for token in line.strip().split():
                    token_clean = token.strip().lower()
                    # Common digest lengths: 32 (MD5), 40 (SHA1), 64 (SHA256)
                    if len(token_clean) in (32, 40, 64) and all(c in "0123456789abcdef" for c in token_clean):
                        needed.add(token_clean)
        except Exception as exc:
            raise ValueError(f"Error reading manifest entry {mf!r}: {exc}")

    # Normalise potential list of digests used
    used = {str(d).strip().lower() for d in digests_used}

    missing = needed - used
    if missing:
        raise ValueError(f"Missing digests required by manifest: {', '.join(sorted(missing))}")

    unused = used - needed
    if unused:
        raise ValueError(f"Digests used but not referenced in any manifest: {', '.join(sorted(unused))}")

    # No mismatches found; everything is present and used correctly
    return None

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    if manifest_files is None:
        raise ValueError("manifest_files must not be None")
    if digests_used is None:
        raise ValueError("digests_used must not be None")

    missing = []
    used = set(digests_used)

    for entry in manifest_files:
        # Support entry being a dict with 'digest' or 'digests' keys, or a simple str
        if isinstance(entry, dict):
            # Prefer a list of digests if present
            digests = entry.get('digests')
            if digests is None:
                # Fallback to a single digest entry
                single = entry.get('digest')
                digests = [single] if single else []
        else:
            # Treat non-dict entry as a single digest string
            digests = [entry]

        for d in digests:
            if d not in used:
                missing.append(d)

    if missing:
        raise RuntimeError(
            "The following required digests are not present in digests_used: "
            + ", ".join(missing)
        )

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    if manifest_files is None and digests_used is None:
        raise ValueError("Both manifest_files and digests_used cannot be None")
    # Collect all digests from the manifest
    manifest_digests = set()
    for entry in manifest_files or []:
        # Accept dicts, objects with .digest, or tuples
        if isinstance(entry, dict):
            digest = entry.get('digest')
        elif hasattr(entry, 'digest'):
            digest = getattr(entry, 'digest')
        elif isinstance(entry, (list, tuple)) and len(entry) > 0:
            digest = entry[0]
        else:
            raise TypeError(f"Unsupported manifest entry type: {type(entry)}")
        if not digest:
            raise ValueError(f"Manifest entry missing digest: {entry}")
        manifest_digests.add(digest)

    # Normalise the used digests into a set
    used = set(digests_used or [])

    # Find digests that are required but not used
    missing = manifest_digests - used
    if missing:
        raise ValueError(f"Missing digests for required files: {', '.join(sorted(missing))}")

    # Find digests that were used but not present in the manifest (optional check)
    unused = used - manifest_digests
    if unused:
        raise ValueError(f"Unexpected unused digests: {', '.join(sorted(unused))}")

    # If we reach here, all required digests are present and used
    return True

def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Ensure prior is the same type of validator
    if not isinstance(prior, type(self)):
        raise TypeError(f"prior must be an instance of {type(self).__name__}")

    # If a version field exists, ensure that prior's version is older
    if hasattr(self, "version") and hasattr(prior, "version"):
        try:
            if prior.version >= self.version:
                raise ValueError(
                    f"prior.version ({prior.version!r}) is not older than current version ({self.version!r})"
                )
        except TypeError:
            # Fall back on string comparison if the objects are not natively comparable
            if str(prior.version) >= str(self.version):
                raise ValueError(
                    f"prior.version ({prior.version!r}) is not older than current version ({self.version!r})"
                )

    # Define a set of attributes that are considered metadata and not part of the core inventory
    metadata_attrs = {"timestamp", "created_at", "updated_at", "metadata", "id"}

    # Determine the set of relevant attributes present in each object
    self_attrs = {k for k in vars(self).keys() if k not in metadata_attrs}
    prior_attrs = {k for k in vars(prior).keys() if k not in metadata_attrs}

    # A prior inventory must not introduce new attributes that are missing in the current one
    missing_in_current = prior_attrs - self_attrs
    if missing_in_current:
        raise ValueError(
            f"prior inventory has attributes missing in the current inventory: {missing_in_current}"
        )

    # For every shared attribute, enforce monotonic or unchanged behaviour
    for attr in prior_attrs:
        curr_val = getattr(self, attr)
        prev_val = getattr(prior, attr)

        # Numeric values should not decrease
        if isinstance(curr_val, (int, float)):
            if prev_val > curr_val:
                raise ValueError(
                    f"Numeric attribute '{attr}' decreased from {prev_val} to {curr_val}"
                )
        else:
            # For non-numeric types, expect exact equality unless the type supports
            # an update pattern (e.g., lists where new elements can be appended).
            # Here we enforce strict equality for simplicity.
            if curr_val != prev_val:
                raise ValueError(
                    f"Attribute '{attr}' changed between versions (prior={prev_val!r}, current={curr_val!r})"
                )

    # If all checks pass, return a truthy value indicating a valid prior
    return True

def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    if not isinstance(prior, type(self)):
        raise TypeError(f"Expected prior to be an instance of {type(self).__name__}, got {type(prior).__name__}")

    # Compare species lists (order is not important)
    if set(self.species) != set(prior.species):
        raise ValueError(
            f"Species sets differ between current inventory and prior.\n"
            f"Current: {sorted(self.species)}\n"
            f"Prior:   {sorted(prior.species)}"
        )

    # Compare parameter lists
    if set(self.parameters) != set(prior.parameters):
        raise ValueError(
            f"Parameter sets differ between current inventory and prior.\n"
            f"Current: {sorted(self.parameters)}\n"
            f"Prior:   {sorted(prior.parameters)}"
        )

    # Compare stoichiometry matrix dimensions
    try:
        s_rows, s_cols = self.stoichiometry_matrix.rows, self.stoichiometry_matrix.cols
        p_rows, p_cols = prior.stoichiometry_matrix.rows, prior.stoichiometry_matrix.cols
    except AttributeError as exc:
        raise AttributeError("Both inventories must have a stoichiometry_matrix with .rows and .cols attributes") from exc

    if (s_rows, s_cols) != (p_rows, p_cols):
        raise ValueError(
            f"Stoichiometry matrix shapes do not match.\n"
            f"Current: {s_rows}x{s_cols}\n"
            f"Prior:   {p_rows}x{p_cols}"
        )

    # Compare propensities matrix dimensions
    try:
        pr_rows, pr_cols = self.propensities.rows, self.propensities.cols
        ppr_rows, ppr_cols = prior.propensities.rows, prior.propensities.cols
    except AttributeError as exc:
        raise AttributeError("Both inventories must have a propensities matrix with .rows and .cols attributes") from exc

    if (pr_rows, pr_cols) != (ppr_rows, ppr_cols):
        raise ValueError(
            f"Propensities matrix shapes do not match.\n"
            f"Current: {pr_rows}x{pr_cols}\n"
            f"Prior:   {ppr_rows}x{ppr_cols}"
        )

    # Optional: check versioning if version attributes exist
    if hasattr(self, "version") and hasattr(prior, "version"):
        if prior.version > self.version:
            raise ValueError(
                f"Prior version ({prior.version}) is newer than current version ({self.version})."
            )
    # If all checks pass, the prior is considered valid
    return None

def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Ensure the prior object is a proper InventoryValidator instance
    if not isinstance(prior, InventoryValidator):
        raise TypeError(f"prior must be an InventoryValidator instance, got {type(prior)!r}")

    # Retrieve the inventory containers.  If the attribute names differ,
    # the calling class is responsible for exposing them under the generic
    # names used here.
    try:
        self_inv = getattr(self, "inventory")
    except AttributeError:
        raise AttributeError("The current object does not expose an 'inventory' attribute.")
    try:
        prior_inv = getattr(prior, "inventory")
    except AttributeError:
        raise AttributeError("The prior object does not expose an 'inventory' attribute.")

    # Verify that every key/value pair in the prior inventory exists identically
    # in the current inventory.  A prior version cannot introduce new
    # inventory items or change existing ones.
    for key, val in prior_inv.items():
        if key not in self_inv:
            raise ValueError(f"Item {key!r} present in prior inventory but missing in current inventory.")
        if self_inv[key] != val:
            raise ValueError(
                f"Item {key!r} differs between inventories: prior has {val!r}, current has {self_inv[key]!r}."
            )

    # Check the relative order of the two inventory versions.  Both objects
    # should expose an attribute named 'version' that can be compared.
    try:
        self_version = getattr(self, "version")
    except AttributeError:
        raise AttributeError("The current object lacks a 'version' attribute required for comparison.")
    try:
        prior_version = getattr(prior, "version")
    except AttributeError:
        raise AttributeError("The prior object lacks a 'version' attribute required for comparison.")

    if prior_version >= self_version:
        raise ValueError(
            f"Prior inventory version ({prior_version}) is not older than "
            f"the current inventory version ({self_version})."
        )

def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Basic type check
    if not isinstance(prior, type(self)):
        raise TypeError("Prior must be an instance of the same InventoryValidator class")

    # Ensure prior is actually older
    try:
        if prior.version >= self.version:
            raise ValueError(
                f"Prior.version ({prior.version}) must be older than the current version ({self.version})"
            )
    except AttributeError:
        raise AttributeError("Both self and prior must have a 'version' attribute")

    # Check that symbols in the prior are subsets of the current inventory
    try:
        missing_params = prior.parameters - self.parameters
        if missing_params:
            raise ValueError(
                f"Prior has parameters {missing_params} not present in the current inventory"
            )
        missing_species = prior.species - self.species
        if missing_species:
            raise ValueError(
                f"Prior has species {missing_species} not present in the current inventory"
            )
    except AttributeError as exc:
        raise AttributeError("Prior must have 'parameters' and 'species' attributes") from exc

    # Compare stoichiometry matrix shape
    try:
        if prior.stoichiometry_matrix.shape != self.stoichiometry_matrix.shape:
            raise ValueError(
                f"Stoichiometry matrix shape mismatch: prior {prior.stoichiometry_matrix.shape} vs current {self.stoichiometry_matrix.shape}"
            )
    except AttributeError as exc:
        raise AttributeError("Prior must have 'stoichiometry_matrix' attribute") from exc

    # Compare propensities shape / length
    try:
        prior_prop = prior.propensities
        curr_prop = self.propensities
        if hasattr(prior_prop, "shape"):
            prior_rows = prior_prop.shape[0]
            curr_rows = curr_prop.shape[0]
        else:
            prior_rows = len(prior_prop)
            curr_rows = len(curr_prop)
        if prior_rows != curr_rows:
            raise ValueError(
                f"Propensity rows mismatch: prior {prior_rows} vs current {curr_rows}"
            )
    except AttributeError as exc:
        raise AttributeError("Prior must have 'propensities' attribute") from exc

    # Validate free symbols in prior propensities
    try:
        all_free = set()
        for expr in prior.propensities:
            # Expressions are assumed to be sympy.Expr or similar
            try:
                free = expr.free_symbols
            except AttributeError:
                # Skip if not a sympy expression
                continue
            all_free.update(free)
        allowed = prior.parameters | prior.species
        unexpected = all_free - allowed
        if unexpected:
            raise ValueError(
                f"Prior propensities contain unknown symbols {unexpected} "
                f"which are not in parameters or species lists"
            )
    except Exception as exc:
        # In case propensities are not iterable or have other issues
        raise ValueError("Failed to validate free symbols in prior propensities") from exc

    # If all checks pass, simply return None
    return None

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Basic type checking
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dict mapping versions to logical path mappings")

    # Ensure version is a string for comparison
    target_version = str(version)

    # Store all logical_path -> set() aggregating from target version onward
    logical_map = {}

    # Iterate through inventory items sorted by version string
    # If the keys are not sortable, we fall back to the insertion order
    try:
        sorted_versions = sorted(inventory.keys())
    except TypeError:
        sorted_versions = inventory.keys()

    for ver in sorted_versions:
        try:
            if ver < target_version:
                continue
        except Exception:
            # If comparison fails, skip to next
            continue

        mapping = inventory.get(ver)
        if not isinstance(mapping, dict):
            continue

        for logical_path, content_files in mapping.items():
            if logical_path not in logical_map:
                logical_map[logical_path] = set()

            # content_files could be a single file or an iterable
            if isinstance(content_files, (list, set, tuple)):
                logical_map[logical_path].update(content_files)
            else:
                logical_map[logical_path].add(content_files)

    if not logical_map:
        raise KeyError(f"No logical paths found for version '{version}' or later in the inventory")

    return logical_map

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Basic validation of inventory
    if not isinstance(inventory, dict):
        raise ValueError("Inventory must be a dictionary mapping versions to path mappings")
    if version not in inventory:
        raise KeyError(f"Version {version!r} not found in inventory")

    # Prepare result mapping for the requested version
    result = {}
    mapping = inventory[version]
    if not isinstance(mapping, dict):
        raise ValueError("Inventory entry for a version must be a dict of logical_path -> iterables of files")
    for logical_path, files in mapping.items():
        if files is None:
            result[logical_path] = set()
        else:
            result[logical_path] = set(files)

    # Handle duplicates from later versions
    # Identify all later versions using simple lexical comparison
    for later_ver, later_mapping in inventory.items():
        if later_ver == version:
            continue
        # try simple numeric conversion for ordering
        try:
            def _key(v):
                return tuple(int(part) for part in v.replace("-", ".").split(".") if part.isdigit())
            order_cmp = _key(later_ver) > _key(version)
        except Exception:
            # fall back to string comparison
            order_cmp = later_ver > version
        if order_cmp:
            if isinstance(later_mapping, dict):
                for logical_path, files in later_mapping.items():
                    if files is None:
                        continue
                    # If the logical path already exists in current result,
                    # add the new files to the set to keep duplicates
                    if logical_path in result:
                        result[logical_path].update(files)
                    else:
                        result[logical_path] = set(files)
    return result

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: `logical_path_in_state` -> `set(content_files)`

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if inventory is None:
        raise ValueError("inventory cannot be None")
    if not isinstance(inventory, dict):
        raise TypeError(f"inventory must be a dict, got {type(inventory).__name__}")

    result = {}
    for logical_path, mapping in inventory.items():
        try:
            if isinstance(mapping, dict):
                # direct mapping: logical_path -> {version: files}
                files = mapping.get(version)
            elif isinstance(mapping, list):
                # optional: list of (version, files) tuples
                files = None
                for v, flist in mapping:
                    if v == version:
                        files = flist
                        break
            else:
                files = None
        except Exception:
            files = None

        if files is None:
            continue

        if isinstance(files, (list, tuple, set)):
            file_set = set(files)
        else:
            file_set = {files}

        if file_set:
            result[logical_path] = file_set

    return result

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a mapping (dict)")

    # If the block is empty, nothing to validate
    if not fixity:
        return True

    for file_path, entry in fixity.items():
        if file_path not in manifest_files:
            raise ValueError(f"Fixity references unknown file: {file_path}")

        if not isinstance(entry, dict):
            raise ValueError(f"Fixity entry for {file_path} must be a mapping")

        # Basic sanity checks: at least one of algorithm or value present
        if not any(k in entry for k in ("algorithm", "value")):
            raise ValueError(f"Fixity entry for {file_path} must contain 'algorithm' or 'value'")

        # If present, algorithm should be a string
        if "algorithm" in entry and not isinstance(entry["algorithm"], str):
            raise ValueError(f"'algorithm' for {file_path} must be a string")

        # If present, value should be a string (most common case)
        if "value" in entry and not isinstance(entry["value"], str):
            raise ValueError(f"'value' for {file_path} must be a string")

    return True

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Basic type check
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")

    # Required top-level keys
    required_keys = {"files"}
    missing = required_keys - set(fixity.keys())
    if missing:
        raise ValueError(f"Missing required keys in fixity block: {', '.join(missing)}")

    files = fixity["files"]
    if not isinstance(files, list):
        raise ValueError("The 'files' key in fixity block must be a list")

    referenced = set()
    for idx, entry in enumerate(files):
        if not isinstance(entry, dict):
            raise ValueError(f"Each entry in 'files' must be a dict (error at index {idx})")
        if "filename" not in entry:
            raise ValueError(f"Missing 'filename' key in entry at index {idx}")
        fname = entry["filename"]
        if not isinstance(fname, str) or not fname:
            raise ValueError(f"Filename must be a non-empty string (error at index {idx})")

        if fname not in manifest_files:
            raise ValueError(f"Fixity references unknown file '{fname}' at index {idx}")
        if fname in referenced:
            raise ValueError(f"Duplicate file reference in fixity: '{fname}' at index {idx}")
        referenced.add(fname)

    # Optional: check for manifest files that are not referenced in fixity
    # If you wish to enforce that every manifest file is referenced, uncomment:
    # missing_refs = set(manifest_files) - referenced
    # if missing_refs:
    #     raise ValueError(f"Fixity block missing entries for: {', '.join(sorted(missing_refs))}")

    return True

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Ensure the manifest is iterable and efficient for membership tests
    manifest_set = set(manifest_files)

    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")

    # Supported hash algorithm names
    supported_algorithms = {'md5', 'sha1', 'sha256', 'sha512'}

    for file_path, hash_info in fixity.items():
        if not isinstance(file_path, str):
            raise ValueError(f"Fixity key must be a file path string; got {type(file_path).__name__}")

        if file_path not in manifest_set:
            raise ValueError(f"Fixity references unknown file: {file_path}")

        if not isinstance(hash_info, dict):
            raise ValueError(f"Hash information for '{file_path}' must be a dictionary")

        # At least one supported hash must be present
        if not supported_algorithms.intersection(hash_info):
            raise ValueError(f"No supported hash found for file: {file_path}")

        for algo, value in hash_info.items():
            if algo not in supported_algorithms:
                raise ValueError(f"Unsupported hash algorithm '{algo}' for file: {file_path}")
            if not isinstance(value, str) or not re.fullmatch(r'[a-fA-F0-9]+', value):
                raise ValueError(f"Invalid hash value for '{algo}' in file: {file_path}")

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a mapping")

    if not isinstance(manifest_files, (set, list, tuple)):
        raise ValueError("Manifest files must be a collection")

    manifest_set = set(manifest_files)

    for checksum_type, block in fixity.items():
        if not isinstance(checksum_type, str):
            raise ValueError(f"Checksum type {checksum_type!r} must be a string")

        # Accept dict mapping file->hash
        if isinstance(block, dict):
            referenced = block.keys()
        # Accept list of entries with a 'file'/'path'/'name' key
        elif isinstance(block, list):
            referenced = []
            for idx, entry in enumerate(block):
                if not isinstance(entry, dict):
                    raise ValueError(f"Entry {idx} in checksum block {checksum_type!r} must be a dict")
                file_key = next((k for k in ("file", "path", "name") if k in entry), None)
                if not file_key:
                    raise ValueError(f"Entry {idx} in checksum block {checksum_type!r} missing file reference")
                referenced.append(entry[file_key])
        else:
            raise ValueError(f"Checksum block for {checksum_type!r} must be a dict or a list")

        # Validate referenced files against the manifest
        for fn in referenced:
            if fn not in manifest_set:
                raise ValueError(f"File {fn!r} referenced in fixity block {checksum_type!r} not in manifest")

def files_list(path):
    """
    Return the files in `path`
    """
    try:
        if not os.path.exists(path):
            raise FileNotFoundError(f"Path '{path}' does not exist.")
        if not os.path.isdir(path):
