def _explore_zipfile(zip_path):
    """Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    import os
    import zipfile
    result = {}
    if not isinstance(zip_path, str) or not zip_path:
        return result
    try:
        with zipfile.ZipFile(zip_path, 'r') as zf:
            temp = {}
            for info in zf.infolist():
                if info.is_dir():
                    continue
                rel_path = info.filename
                name = os.path.basename(rel_path)
                base, _ = os.path.splitext(name)
                # Initialize nested dict for this base if not present
                if base not in temp:
                    temp[base] = {}
                # Read the file contents
                try:
                    content = zf.read(info)
                except Exception:
                    # Skip files that cannot be read
                    continue
                temp[base][rel_path] = content
            # Filter to keep only bases that contain an XML file
            for base, files in temp.items():
                has_xml = any(fn.lower().endswith('.xml') for fn in files)
                if has_xml:
                    result[base] = files
    except Exception:
        # On any error (e.g., file not found, invalid zip) return empty dict
        return {}
    return result

