def _explore_zipfile(zip_path):
    """Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path

    Returns
    -------
    dict
        Mapping of package base name to a dictionary of file paths and their data.
    """
    import zipfile
    import os

    packages = {}
    try:
        with zipfile.ZipFile(zip_path, 'r') as zf:
            # First, find all XML files to identify package roots
            xml_map = {}
            for info in zf.infolist():
                if info.is_dir():
                    continue
                name = info.filename
                if name.lower().endswith('.xml'):
                    base = os.path.splitext(os.path.basename(name))[0]
                    dir_path = os.path.dirname(name)
                    xml_map[dir_path] = base

            # Now collect all files belonging to each identified package
            for info in zf.infolist():
                if info.is_dir():
                    continue
                name = info.filename
                dir_path = os.path.dirname(name)
                if dir_path in xml_map:
                    base = xml_map[dir_path]
                    if base not in packages:
                        packages[base] = {}
                    try:
                        content = zf.read(info)
                    except Exception:
                        # Skip files that cannot be read
                        continue
                    packages[base][name] = content
    except (FileNotFoundError, zipfile.BadZipFile, OSError):
        # Return an empty dictionary if the zip cannot be processed
        return {}
    return packages

