    """
    Return a pretty formatted representation of self.

    Parameters
    ----------
    indent : int, optional
        Number of spaces to use for indentation in pretty output. Default is 0.
    debug : bool, optional
        If True include additional debug information such as class name and module.
        Default is False.

    Returns
    -------
    str
        A human‑readable, prettified string representation of ``self``.
    """
    # Try to import pretty‑printer. If unavailable fall back to a simple repr.
    try:
        import pprint
    except Exception:
        # Fall back to the built‑in representation with minimal formatting.
        return str(self)

    try:
        # If debug mode, show class path and selected attributes for clarity.
        if debug:
            class_path = f"{self.__class__.__module__}.{self.__class__.__qualname__}"
            # Show public attributes only (excluding private/protected and methods).
            attrs = {
                k: v
                for k, v in vars(self).items()
                if not k.startswith("_") and not callable(v)
            }
            pretty_content = pprint.pformat(attrs, indent=indent)
            return f"{class_path}:\n{pretty_content}"

        # Default: pretty‑print the output of the object's __repr__.
        # Most modern objects provide a useful __repr__ that returns a string.
        # We pass that string through pformat to add newlines/indentation
        # for readability.
        repr_value = repr(self)
        # Use pformat's width=80 by default which is reasonable.
        return pprint.pformat(repr_value, indent=indent)

    except Exception:
        # If anything goes wrong, fall back to a plain string representation.
        return str(self)

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    try:
        if not isinstance(indent, int) or indent < 0:
            raise ValueError("indent must be a non‑negative integer")
        from pprint import pformat
        base_repr = pformat(self, indent=indent)
        if debug:
            try:
                state_repr = pformat(vars(self), indent=indent)
            except Exception:
                state_repr = "<unavailable>"
            return f"DEBUG: {base_repr}\nInternal state: {state_repr}"
        return base_repr
    except Exception as exc:  # pragma: no cover
        return f"<Unable to pretty print: {exc}>"

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    try:
        # Validate indent argument
        if not isinstance(indent, int):
            raise TypeError("indent must be an integer")
        if indent < 0:
            raise ValueError("indent must be non-negative")

        # Try JSON serialization if the object is a basic container
        try:
            import json
            if isinstance(self, (dict, list, tuple, set)):
                # Convert sets to lists for JSON compatibility
                data = self if not isinstance(self, set) else list(self)
                return json.dumps(data, default=str, indent=indent, sort_keys=True)
        except Exception:
            # Fall back to pretty printer if JSON fails
            pass

        # Fallback to pprint for general objects
        import pprint
        repr_str = pprint.pformat(
            self,
            width=60 + indent * 2,
            indent=indent,
            depth=None,
            compact=False
        )

        if debug:
            return f"{repr_str}\n<type: {type(self).__name__} id: {id(self)}>"

        return repr_str

    except Exception as e:
        # Give a helpful message while preserving the original representation
        return f"Pretty formatting error: {e} (object: {repr(self)})"

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expressions
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    try:
        from sympy import simplify, sympify
    except Exception:
        # sympy is required for symbolic manipulation; if import fails,
        # fall back to returning the original list.
        return list(args)

    # Convert all arguments to sympy expressions if possible
    sympy_args = []
    for arg in args:
        try:
            sympy_args.append(sympify(arg))
        except Exception:
            sympy_args.append(arg)

    # Simplify each expression applying absorption rules
    simplified = []
    for expr in sympy_args:
        try:
            simplified_expr = simplify(expr)
        except Exception:
            simplified_expr = expr
        # Avoid duplicates
        if all(simplified_expr != existing for existing in simplified):
            simplified.append(simplified_expr)

    return simplified

def on(self, hook):
    """Decorator function to add a new handler to the registry.

    Args:
        hook (HookType): Hook attribute for which to register the handler.

    Returns:
        callable: Decorator for registering listeners for the specified
        hook.

    """
    def decorator(func):
        if not callable(func):
            raise TypeError(f"The object {func!r} specified as a handler is not callable.")
        if not hasattr(self, 'register_hook'):
            raise AttributeError("The object does not provide a 'register_hook' method.")
        try:
            self.register_hook(hook, func)
        except Exception as exc:
            raise RuntimeError(f"Failed to register hook {hook!r} for handler {func.__name__}: {exc}") from exc
        return func
    return decorator

