            try:
                # Validate the object itself if requested
                if validate_objects and hasattr(obj, 'validate'):
                    is_valid = bool(obj.validate())
                # Optionally check the object's digest
                if is_valid and check_digests and hasattr(obj, 'digest') and hasattr(obj, 'content'):
                    # In a real implementation we would compute the digest of the content and compare
                    computed_digest = obj.content and hash(obj.content)
                    if obj.digest != computed_digest:
                        is_valid = False
                        if show_warnings:
                            print(f"Digest mismatch for object {obj}: expected {obj.digest}, got {computed_digest}")
            except Exception as exc:
                # Any exception during validation is treated as a failure
                is_valid = False
                if show_warnings:
                    print(f"Validation failed for object {obj}: {exc}")

            if is_valid:
                good_objects += 1

        return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """
    Validate storage root hierarchy.

    Parameters
    ----------
    validate_objects : bool, optional
        If True, each object will be checked for required fields. Default is True.
    check_digests : bool, optional
        If True, compute and compare digests for data fields. Default is True.
    show_warnings : bool, optional
        If True, print warning messages for invalid objects. Default is False.

    Returns
    -------
    tuple
        A tuple of two integers: (num_objects, good_objects)
        where num_objects is the total number of objects examined and
        good_objects is the number of objects that passed validation.
    """
    # Count of examined objects and those that passed validation
    num_objects = 0
    good_objects = 0

    # Ensure there is a storage root to work with
    root = getattr(self, 'storage_root', None)
    if root is None:
        if show_warnings:
            print("validate_hierarchy: No storage_root attribute found.")
        return 0, 0

    # Import hashlib only if digest checks are requested
    if check_digests:
        try:
            import hashlib
        except ImportError as exc:
            if show_warnings:
                print(f"validate_hierarchy: hashlib module unavailable: {exc}")
            check_digests = False

    def _compute_digest(data):
        """Compute a SHA256 digest of the given data."""
        try:
            # Ensure data is bytes; if it's a string, encode it
            if isinstance(data, str):
                data_bytes = data.encode('utf-8')
            else:
                data_bytes = data
            return hashlib.sha256(data_bytes).hexdigest()
        except Exception as exc:
            if show_warnings:
                print(f"_compute_digest: error computing digest: {exc}")
            return None

    def _walk(node):
        nonlocal num_objects, good_objects
        # If node is a dictionary, treat it as a collection of objects
        if isinstance(node, dict):
            for key, child in node.items():
                num_objects += 1
                is_valid = True

                if validate_objects:
                    if not isinstance(child, dict):
                        is_valid = False
                        if show_warnings:
                            print(f"Invalid object '{key}': expected dict, got {type(child).__name__}")
                    else:
                        # Example required field: 'id'
                        if 'id' not in child:
                            is_valid = False
                            if show_warnings:
                                print(f"Object '{key}' missing required 'id' field")
                        # Example required field: 'name'
                        if 'name' not in child:
                            is_valid = False
                            if show_warnings:
                                print(f"Object '{key}' missing required 'name' field")

                if check_digests and isinstance(child, dict):
                    digest_expected = child.get('digest')
                    if digest_expected:
                        data = child.get('data')
                        if data is not None:
                            digest_actual = _compute_digest(data)
                            if digest_actual != digest_expected:
                                is_valid = False
                                if show_warnings:
                                    print(f"Digest mismatch for object '{key}': expected {digest_expected}, got {digest_actual}")

                if is_valid:
                    good_objects += 1

                # Recurse into the child if it's a container
                if isinstance(child, (dict, list)):
                    _walk(child)

        elif isinstance(node, list):
            for item in node:
                _walk(item)
        else:
            # Leaf nodes are ignored in counting; they don't represent objects
            pass

    try:
        _walk(root)
    except Exception as exc:
        if show_warnings:
            print(f"Error during hierarchy validation: {exc}")
        # In case of unexpected errors, return what we have so far
        return num_objects, good_objects

    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    import os
    import hashlib

    if not hasattr(self, 'root_dir'):
        raise AttributeError("Instance must have a 'root_dir' attribute pointing to the storage root.")

    num_objects = 0
    good_objects = 0

    # Recursively walk the root directory
    for dirpath, dirnames, filenames in os.walk(self.root_dir):
        for fname in filenames:
            # Skip bookkeeping or metadata files if present
            if fname.endswith(('.meta', '.checksum')):
                continue

            obj_path = os.path.join(dirpath, fname)
            num_objects += 1

            try:
                # Validate object existence if required
                if validate_objects and not os.path.exists(obj_path):
                    if show_warnings:
                        print(f"[WARN] Object missing: {obj_path}")
                    continue

                # Validate checksum/digest if required
                if check_digests:
                    # Look for an accompanying .checksum file
                    checksum_file = f"{obj_path}.checksum"
                    if os.path.exists(checksum_file):
                        with open(checksum_file, 'r', encoding='utf-8') as f:
                            expected_checksum = f.read().strip()
                        # Compute actual checksum
                        hash_obj = hashlib.sha256()
                        with open(obj_path, 'rb') as f:
                            for chunk in iter(lambda: f.read(8192), b''):
                                hash_obj.update(chunk)
                        actual_checksum = hash_obj.hexdigest()
                        if actual_checksum != expected_checksum:
                            if show_warnings:
                                print(f"[WARN] Checksum mismatch for {obj_path}")
                            continue
                    else:
                        # No checksum file present; assume valid if existence check passes
                        pass

                # If reached here, object is considered valid
                good_objects += 1

            except Exception as exc:
                if show_warnings:
                    print(f"[ERROR] Validation failed for {obj_path}: {exc}")
                # Continue scanning other objects

    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        tuple[int, int]: num_objects - number of objects checked,
                         good_objects - number of objects checked that were found to be valid
    """
    # Validate argument types
    for arg_name, arg_val in (('validate_objects', validate_objects),
                              ('check_digests', check_digests),
                              ('show_warnings', show_warnings)):
        if not isinstance(arg_val, bool):
            raise TypeError(f"Argument '{arg_name}' must be a boolean, got {type(arg_val).__name__}")

    # Gather objects from the hierarchy.  Subclasses may expose the collection
    # in different ways; we try a few common patterns.
    try:
        if hasattr(self, 'objects'):
            objects = list(self.objects)
        elif hasattr(self, 'get_objects'):
            objects = list(self.get_objects())
        elif hasattr(self, 'storage'):  # fallback to an attribute named 'storage'
            objects = list(self.storage)
        else:
            raise AttributeError("No accessible object collection found")
    except Exception as exc:
        raise RuntimeError(f"Unable to retrieve objects from hierarchy: {exc}") from exc

    num_objects = len(objects)
    good_objects = 0

    for idx, obj in enumerate(objects, start=1):
        try:
            # If the object has a validate method, invoke it.  Otherwise we
            # optimistically assume it is valid.
            if hasattr(obj, 'validate') and callable(getattr(obj, 'validate')):
                # Pass keyword arguments if the signature accepts them
                try:
                    # Attempt to call with both options
                    result = obj.validate(check_digests=check_digests, show_warnings=show_warnings)
                except TypeError:
                    # Fallback to positional arguments if the validate signature
                    # does not support keyword-only parameters
                    result = obj.validate(check_digests, show_warnings)
                if validate_objects:
                    # The validate method may return a bool or None.  Treat
                    # a truthy return value as success.
                    is_valid = bool(result)
                else:
                    is_valid = True
            else:
                # No validate method; assume valid
                is_valid = True
        except Exception as e:
            if show_warnings:
                try:
                    obj_repr = repr(obj)
                except Exception:
                    obj_repr = str(obj)
                print(f"WARNING: Validation of object {obj_repr} failed (object #{idx}): {e}")
            is_valid = False

        if is_valid:
            good_objects += 1

    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    # Collect objects from the hierarchy.  The actual storage is
    # implementation‑specific, so we allow any attribute that
    # behaves like an iterable of objects.
    try:
        objects = getattr(self, 'objects', [])
    except Exception:
        objects = []

    num_objects = 0
    good_objects = 0
    warnings = []

    # Helper to compute a digest of a byte‑ish object
    def _digest(data):
        import hashlib
        if isinstance(data, (bytes, bytearray)):
            return hashlib.sha256(data).hexdigest()
        # if data is a file‑like object, read it in chunks
        if hasattr(data, 'read'):
            hasher = hashlib.sha256()
            while True:
                chunk = data.read(8192)
                if not chunk:
                    break
                hasher.update(chunk)
            return hasher.hexdigest()
        # fallback: serialize via repr
        return hashlib.sha256(repr(data).encode('utf-8')).hexdigest()

    for obj in objects:
        num_objects += 1
        valid = True

        # Basic object validation
        if validate_objects:
            validator = getattr(obj, 'validate', None)
            if callable(validator):
                try:
                    validator()
                    good_objects += 1
                except Exception:
                    valid = False
                continue  # skip digest if basic validation already failed

        # Digest check
        if check_digests:
            expected = getattr(obj, 'digest', None) or getattr(obj, 'expected_digest', None)
            actual = None
            try:
                if hasattr(obj, 'content'):
                    actual = _digest(obj.content)
                elif hasattr(obj, 'data'):
                    actual = _digest(obj.data)
                elif isinstance(obj, (bytes, bytearray)):
                    actual = _digest(obj)
                else:
                    # Last resort: serialize the object
                    actual = _digest(ret:=repr(obj))
            except Exception:
                valid = False

            if expected is not None and actual is not None and expected != actual:
                valid = False

        if not valid:
            if show_warnings:
                warnings.append(f"Object {obj} failed validation or digest check.")

    if show_warnings:
        for w in warnings:
            print(w)

    return num_objects, good_objects

def initialize(self):
    """Create and initialize a new OCFL storage root."""
    from pathlib import Path
    import json

    root = Path(self.root)
    # If the root already exists, ensure it's empty (or raise an error)
    if root.exists():
        if any(root.iterdir()):
            raise ValueError(f"Root {root} already exists and is not empty.")
        # Already exists and empty – consider it initialized
        return

    try:
        root.mkdir(parents=True)
    except OSError as exc:
        raise ValueError(f"Failed to create root directory {root}: {exc}") from exc

    # Create mandatory OCFL directories
    ocfl_dir = root / ".ocfl"
    try:
        ocfl_dir.mkdir()
    except OSError as exc:
        raise ValueError(f"Failed to create directory {ocfl_dir}: {exc}") from exc

    objects_dir = ocfl_dir / "objects"
    try:
        objects_dir.mkdir()
    except OSError as exc:
        raise ValueError(f"Failed to create directory {objects_dir}: {exc}") from exc

    # Create metadata directory
    metadata_dir = ocfl_dir / "metadata"
    metadata_dir.mkdir()

    # Write a default root configuration file
    config = {"ocfl_version": "1.0", "root_layout": "standard"}
    config_path = metadata_dir / "root.json"
    try:
        config_path.write_text(json.dumps(config, indent=2))
    except OSError as exc:
        raise ValueError(f"Failed to write config file {config_path}: {exc}") from exc

    # Create a lock file to prevent concurrent access
    lock_file = ocfl_dir / "LOCK"
    try:
        lock_file.touch()
    except OSError as exc:
        raise ValueError(f"Failed to create lock file {lock_file}: {exc}") from exc

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        raise TypeError("version must be a string")

    parts = version.strip().split('.')
    if not parts or any(p == '' for p in parts):
        raise ValueError("invalid version format")

    new_parts = []
    for i, part in enumerate(parts):
        if not part.isdigit():
            raise ValueError(f"non-numeric component in version: '{part}'")
        # Increment the last component only.
        if i == len(parts) - 1:
            num = int(part) + 1
            # Preserve leading zeros if present.
            width = len(part)
            new_part = str(num).zfill(width)
        else:
            new_part = part
        new_parts.append(new_part)

    return '.'.join(new_parts)

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        raise TypeError(f"Expected string, got {type(version).__name__}")
    v = version.strip()
    if not v.isdigit():
        raise ValueError(f"Invalid version string: {version!r}")

    # Convert to integer and increment
    num = int(v)
    next_num = num + 1

    # Preserve leading zeros if present in the original string
    if v.startswith("0"):
        width = len(v)
        if next_num < 10 ** width:
            return str(next_num).zfill(width)

    return str(next_num)

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not version:
        return ""
    # Find the longest trailing digit sequence
    i = len(version) - 1
    while i >= 0 and version[i].isdigit():
        i -= 1
    # No trailing digits found; return as is
    if i == len(version) - 1:
        return version
    numeric_part = version[i + 1 :]
    prefix = version[: i + 1]
    try:
        incremented = int(numeric_part) + 1
    except ValueError:
        return version
    # Preserve original width with leading zeros if the increment doesn't increase length
    if len(str(incremented)) < len(numeric_part):
        new_numeric = str(incremented).zfill(len(numeric_part))
    else:
        new_numeric = str(incremented)
    return prefix + new_numeric

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Ensure we have a structure to capture differences
    if not hasattr(self, "_diff_digests"):
        self._diff_digests = {}
    # Path to the root inventory (assumed to be stored in self.root_inventory_file)
    if not hasattr(self, "root_inventory_file"):
        raise AttributeError("Cannot validate without 'root_inventory_file' attribute")
    try:
        with open(self.root_inventory_file, "r", encoding="utf-8") as fh:
            root_inventory = json.load(fh)
    except FileNotFoundError:
        raise ValueError(f"Root inventory file '{self.root_inventory_file}' not found")
    except json.JSONDecodeError as err:
        raise ValueError(f"Root inventory file '{self.root_inventory_file}' is not valid JSON: {err}")

    # Validate each version directory
    for vd in version_dirs:
        inv_path = os.path.join(self.base_dir, vd, "inventory.json")
        if not os.path.isfile(inv_path):
            raise ValueError(f"Missing inventory file for version directory '{vd}'")
        try:
            with open(inv_path, "r", encoding="utf-8") as fh:
                version_inv = json.load(fh)
        except json.JSONDecodeError as err:
            raise ValueError(f"Inventory file '{inv_path}' is not valid JSON: {err}")

        # It should be a mapping of content path to digest string
        if not isinstance(version_inv, dict):
            raise ValueError(f"Inventory file '{inv_path}' should contain a mapping of content to digest")

        # Check that the inventory includes at least all entries up to this version
        # (we assume root inventory contains the complete set)
        for path, digest in version_inv.items():
            if path not in root_inventory:
                # The root inventory should contain all entries; missing ones are suspicious
                # but not necessarily an error if the version introduces new content
                # We'll ignore for now
                continue

            root_digest = root_inventory[path]
            if digest != root_digest:
                # Record the discrepancy
                self._diff_digests.setdefault(path, []).append(
                    (vd, root_digest, digest)
                )

    return self

def validate_version_inventories(self, version_dirs):
        """Each version SHOULD have an inventory up to that point.
        Also keep a record of any content digests different from those in the
        root inventory so that we can also check them when validating the
        content.
        version_dirs is an array of version directory names and is assumed
        to be in version sequence (1, 2, 3...).
        """
        # Validate input
        if not isinstance(version_dirs, (list, tuple)):
            raise TypeError("version_dirs must be a list or tuple of directory names")
        # Helper to load inventory (JSON) from a path
        def _load_inventory(inv_path):
            try:
                with open(inv_path, "r", encoding="utf-8") as fh:
                    return json.load(fh)
            except FileNotFoundError as exc:
                raise FileNotFoundError(f"Inventory file not found: {inv_path}") from exc
            except ValueError as exc:
                raise ValueError(f"Inventory file not valid JSON: {inv_path}") from exc

        # Load the root inventory (assumed to be stored in self.root_inventory_path)
        root_inv_path = getattr(self, "root_inventory_path", None)
        if root_inv_path is None:
            raise AttributeError("self.root_inventory_path is required for validation")
        root_inventory = _load_inventory(root_inv_path)

        # Keep record of differences
        self._different_digests = {}

        # Track all files seen so far
        seen_files = set()

        for idx, vd in enumerate(version_dirs, start=1):
            inv_path = os.path.join(vd, "inventory.json")
            inventory = _load_inventory(inv_path)

            # Ensure current inventory contains all files seen so far (cumulative)
            missing_in_current = seen_files - set(inventory.keys())
            if missing_in_current:
                raise ValueError(
                    f"Inventory in {vd} is missing entries: {sorted(missing_in_current)}"
                )

            # Compare each file's digest with the root inventory
            for fname, digest in inventory.items():
                root_digest = root_inventory.get(fname)
                if root_digest is None:
                    raise ValueError(f"File {fname!r} in {vd} is not present in root inventory")
                if digest != root_digest:
                    self._different_digests.setdefault(fname, []).append(idx)

            # Update seen files
            seen_files.update(inventory.keys())

        # Return the dictionary of differences for convenience
        return self._different_digests

def find_path_type(path):
    """
    Return a string indicating the type of thing at the given path.

    Return values:
        'root'   - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file'   - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    if not path:
        return "invalid path"

    try:
        if not os.path.exists(path):
            return "path not found"

        if os.path.isfile(path):
            return "file"

        if os.path.isdir(path):
            # 1. check if the directory itself contains a Namaste file "0=*"
            for entry in os.listdir(path):
                full = os.path.join(path, entry)
                if os.path.isfile(full) and entry.startswith("0="):
                    return "object"

            # 2. if not, look for a subdirectory that contains a Namaste file
            for entry in os.listdir(path):
                subdir = os.path.join(path, entry)
                if os.path.isdir(subdir):
                    for subentry in os.listdir(subdir):
                        subfull = os.path.join(subdir, subentry)
                        if os.path.isfile(subfull) and subentry.startswith("0="):
                            return "root"

            # 3. If nothing matches, it is not a recognizable OCFL structure
            return "unknown directory type"

        # Should not reach here
        return "unrecognized path type"

    except Exception as exc:
        return f"error: {exc}"

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os
    try:
        if not os.path.exists(path):
            return f"Path does not exist: {path}"
        if os.path.isfile(path):
            return "file"
        if os.path.isdir(path):
            # Look for a file or directory that starts with '0=' which indicates an OCFL object
            for entry in os.listdir(path):
                if entry.startswith("0="):
                    return "object"
            # If no '0=' entries, consider it the OCFL storage root
            return "root"
    except OSError as exc:
        return f"Error accessing path '{path}': {exc}"
    except Exception as exc:
        return f"Unexpected error for path '{path}': {exc}"

def amend_bzparams(self, params, bug_ids):
        """Amend the Bugzilla params"""
        if not isinstance(params, dict):
            raise ValueError("params must be a dictionary")
        # Normalize bug_ids to a list of strings
        ids = []
        if bug_ids is None:
            ids = []
        elif isinstance(bug_ids, (int, str)):
            ids = [str(bug_ids)]
        elif hasattr(bug_ids, "__iter__"):
            for bid in bug_ids:
                try:
                    ids.append(str(int(bid)))
                except Exception as exc:
                    raise ValueError(f"Invalid bug ID '{bid}'") from exc
        else:
            raise ValueError("bug_ids must be an int, str, or iterable of IDs")

        if ids:
            params['ids'] = ",".join(ids)
        return params

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""

    # Ensure params is a dictionary
    if params is None:
        params = {}
    if not isinstance(params, dict):
        raise ValueError("params must be a dict")

    if bug_ids is None:
        return params

    # Convert bug_ids to a comma separated string
    if isinstance(bug_ids, str):
        ids_str = bug_ids.strip()
    elif isinstance(bug_ids, (list, tuple, set)):
        # Filter out None values just in case
        ids_str = ','.join(str(b) for b in bug_ids if b is not None)
    else:
        ids_str = str(bug_ids)

    if ids_str:
        existing = params.get('ids')
        if existing:
            # Merge unique ids
            combined = set(existing.split(',')) | set(ids_str.split(','))
            params['ids'] = ','.join(combined)
        else:
            params['ids'] = ids_str

    return params

def amend_bzparams(self, params, bug_ids):
        """Amend the Bugzilla params"""
        if params is None:
            params = {}
        try:
            if bug_ids:
                # Normalize bug_ids to a comma‑separated string
                if isinstance(bug_ids, (int, float, str)):
                    params['ids'] = str(bug_ids)
                else:
                    params['ids'] = ','.join(str(bid) for bid in bug_ids)
        except Exception as exc:
            raise BugException(f"Error amending Bugzilla params: {exc}") from exc
        return params

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
