def parse_arguments(*unparsed_arguments):
    """
    Given command-line arguments with which this script was invoked, parse the arguments and
    return them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    """
    parser = argparse.ArgumentParser()
    try:
        namespace, _ = parser.parse_known_args(list(unparsed_arguments))
    except Exception as exc:
        raise RuntimeError(f"Argument parsing failed: {exc}") from exc
    return {"global": namespace}

def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    # Validate inputs
    if not isinstance(subparsers, dict):
        raise TypeError("subparsers must be a dict mapping names to argparse.ArgumentParser instances")
    # Accept any iterable for arguments, convert to list for multiple passes
    if not isinstance(unparsed_arguments, (list, tuple)):
        try:
            unparsed_arguments = list(unparsed_arguments)
        except Exception as exc:
            raise TypeError("unparsed_arguments must be a list, tuple, or iterable") from exc

    parsed = {}
    # None until first subparser
    common_unknowns = None

    for name, parser in subparsers.items():
        if not hasattr(parser, 'parse_known_args'):
            raise TypeError(f"The object for subparser '{name}' does not have a 'parse_known_args' method")
        try:
            namespace, unknown = parser.parse_known_args(unparsed_arguments)
        except Exception as exc:
            # Propagate parser errors to caller
            raise RuntimeError(f"Error parsing arguments for subparser '{name}'") from exc
        parsed[name] = namespace
        unknown_set = set(unknown)
        if common_unknowns is None:
            common_unknowns = unknown_set
        else:
            common_unknowns &= unknown_set

    if common_unknowns is None:
        # No subparsers, so everything is remaining
        remaining = list(unparsed_arguments)
    else:
        # Preserve original order of remaining arguments as they appear in the input
        remaining = [arg for arg in unparsed_arguments if arg in common_unknowns]

    return parsed, remaining

def parse_subparser_arguments(unparsed_arguments, subparsers):
    """
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    """
    parsed = {}
    unknown_lists = []

    for name, parser in subparsers.items():
        try:
            namespace, unknown = parser.parse_known_args(list(unparsed_arguments))
            parsed[name] = namespace
            unknown_lists.append(unknown)
        except Exception:
            # If parsing fails for a subparser, still record a None namespace
            parsed[name] = None
            unknown_lists.append([])

    if unknown_lists:
        # Arguments not claimed by any subparser are those that remain unknown for *all* subparsers
        remaining = [arg for arg in unparsed_arguments
                     if all(arg in unknown for unknown in unknown_lists)]
    else:
        remaining = list(unparsed_arguments)

    return parsed, remaining

