def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    result = {}
    for d in dicts:
        if not isinstance(d, dict):
            raise TypeError("All elements in 'dicts' must be dictionaries")
        for k, v in d.items():
            if not isinstance(v, (int, float)):
                raise TypeError(f"Value for key '{k}' must be numeric")
            result[k] = result.get(k, 0) + v
    return result

