    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    # Validate that dicts is iterable
    try:
        iterator = iter(dicts)
    except TypeError as exc:
        raise TypeError("The argument 'dicts' must be an iterable of dictionaries") from exc

    result = {}
    for idx, d in enumerate(iterator):
        if not isinstance(d, dict):
            raise TypeError(f"Element at position {idx} is not a dictionary: {d!r}")
        for key, value in d.items():
            if key in result:
                try:
                    result[key] += value
                except TypeError as exc:
                    raise TypeError(f"Cannot sum values for key '{key}': {result[key]!r} + {value!r}") from exc
            else:
                # Ensure value is a numeric type that can be summed; otherwise just set it
                result[key] = value
    return result

