def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    if not url:
        return ''
    if not url_args:
        return url

    pattern = re.compile(r'{([^{}]+)}')

    def _replace(match):
        key = match.group(1)
        if key not in url_args:
            return match.group(0)
        value = url_args[key]
        if isinstance(value, (list, tuple)):
            value = ','.join(str(v) for v in value)
        else:
            value = str(value)
        # Encode for URL safe usage
        return urllib.parse.quote(value)

    try:
        return pattern.sub(_replace, url)
    except Exception:
        # On error, return the original URL
        return url

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""

    if not url:
        return url

    # Ensure url_args is a mapping; if not, try to convert
    if not isinstance(url_args, dict):
        try:
            url_args = dict(url_args)
        except Exception:
            return url

    import re

    # Pattern matches {key} in the URL
    pattern = re.compile(r'\{([^{}]+)\}')

    # Function to replace each match
    def replace_match(match):
        key = match.group(1)
        if key in url_args:
            value = url_args[key]
            # If the value is None, replace it with an empty string
            if value is None:
                return ''
            # URL‑encode the value to ensure a valid URL
            try:
                from urllib.parse import quote_plus
                encoded = quote_plus(str(value))
            except Exception:
                encoded = str(value)
            return encoded
        # If no value provided, keep the placeholder unchanged
        return match.group(0)

    # Perform the substitution
    return pattern.sub(replace_match, url)

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""

    if not isinstance(url, str):
        return url

    if not url_args:
        return url

    # Ensure url_args is a mapping
    if not isinstance(url_args, dict):
        raise TypeError("url_args must be a dict")

    for key, value in url_args.items():
        # Normalize key and value to strings
        try:
            key_str = str(key)
        except Exception:
            continue  # skip invalid keys

        if value is None:
            replace_with = ''
        else:
            try:
                replace_with = str(value)
            except Exception:
                replace_with = ''

        # Percent‑encode the replacement value for safety
        try:
            encoded = urllib.parse.quote(replace_with, safe='')
        except Exception:
            encoded = replace_with

        # Replace common placeholder patterns
        url = url.replace(f'{{{key_str}}}', encoded)
        url = url.replace(f'<{key_str}>', encoded)
        url = url.replace(f'%7B{key_str}%7D', encoded)
        url = url.replace(f'%7B{key_str}%7D', encoded)  # encoded braces

    return url

