def was_processed(processed, path_name, verbose):
    """
    Check if a file or directory has already been processed.

    To prevent recursion, expand the path name to an absolute path
    and call this function with a set that will store all the entries
    and the entry to test.  If the entry is already in the set,
    report the issue and return ``True``.  Otherwise, add the entry
    to the set and return ``False`` to allow the path to be processed.

    Args:
        processed: Set (or set-like object) to store processed pathnames.
                If ``None`` an empty set will be used.
        path_name: Path to a directory or file.  It may be relative.
        verbose:   ``True`` if verbose output is requested.

    Returns:
        bool: ``True`` if the path is already in the set, ``False`` otherwise.
    """
    try:
        import os
    except Exception:
        # If os cannot be imported, fail silently and consider it processed
        if verbose:
            print("[was_processed] os module not available; treating as processed")
        return True

    # Ensure we have a set-like container
    if processed is None:
        processed = set()
    elif not hasattr(processed, "add") or not hasattr(processed, "__contains__"):
        if verbose:
            print("[was_processed] processed is not set-like; treating as unprocessed")
        processed = set()

    # Validate input path_name
    if not isinstance(path_name, (str, bytes)):
        if verbose:
            print(f"[was_processed] path_name={path_name!r} is not a string; treating as processed")
        return True

    # Resolve to absolute, normalized, and canonical path
    try:
        abs_path = os.path.abspath(path_name)
        abs_path = os.path.normpath(abs_path)
        abs_path = os.path.realpath(abs_path)
    except Exception as e:
        if verbose:
            print(f"[was_processed] could not resolve path {path_name!r}: {e}")
        return True

    if abs_path in processed:
        if verbose:
            print(f"[was_processed] already processed: {abs_path}")
        return True

    # Not processed yet; add to set
    try:
        processed.add(abs_path)
    except Exception as e:
        if verbose:
            print(f"[was_processed] failed to add {abs_path!r} to processed set: {e}")
        # If we cannot add, still treat as processed to avoid duplicate work
        return True

    if verbose:
        print(f"[was_processed] added: {abs_path}")
    return False

def vertex3tuple(vertices):
    """return 3 points for each vertex of the polygon. This will include the vertex and the 2 points on both sides of the vertex::

        polygon with vertices ABCD
        Will return
        DAB, ABC, BCD, CDA -> returns 3tuples
        #A    B    C    D  -> of vertices
    """
    try:
        return vertex3tuple._vertex3tuple
    except AttributeError:
        pass
    if vertices is None:
        raise ValueError("vertices must not be None")
    try:
        verts = list(vertices)
    except TypeError:
        raise TypeError("vertices must be an iterable of points")
    n = len(verts)
    if n == 0:
        vertex3tuple._vertex3tuple = []
    else:
        triples = []
        for i in range(n):
            prev = verts[(i - 1) % n]
            curr = verts[i]
            nxt = verts[(i + 1) % n]
            triples.append((prev, curr, nxt))
        vertex3tuple._vertex3tuple = triples
    return vertex3tuple._vertex3tuple

def vertex3tuple(vertices):
    """return 3 points for each vertex of the polygon. This will include the vertex and the 2 points on both sides of the vertex::

        polygon with vertices ABCD
        Will return
        DAB, ABC, BCD, CDA -> returns 3tuples
        #A    B    C    D  -> of vertices
    """
    try:
        if not vertices:
            return []
    except Exception:
        return []
    try:
        n = len(vertices)
        if n == 0:
            return []
        result = []
        for i in range(n):
            prev_vertex = vertices[(i - 1) % n]
            curr_vertex = vertices[i]
            next_vertex = vertices[(i + 1) % n]
            result.append((prev_vertex, curr_vertex, next_vertex))
        return result
    except Exception:
        return []

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not isinstance(number, int):
        raise TypeError(f"number must be an int, got {type(number).__name__}")
    if not isinstance(alphabet, list) or len(alphabet) < 2:
        raise ValueError("alphabet must be a list of at least two single-character strings")
    for i, ch in enumerate(alphabet):
        if not isinstance(ch, str) or len(ch) != 1:
            raise ValueError(f"alphabet element at index {i} must be a single-character string")

    base = len(alphabet)
    if base < 2:
        raise ValueError("alphabet must contain at least two characters to form a base")

    # Handle sign
    negative = number < 0
    abs_number = -number if negative else number

    # Special case for zero
    if abs_number == 0:
        result = alphabet[0]
    else:
        digits = []
        while abs_number > 0:
            rem = abs_number % base
            digits.append(alphabet[rem])
            abs_number //= base
        result = "".join(reversed(digits))

    # Apply padding if requested
    if padding is not None:
        if not isinstance(padding, int) or padding < 0:
            raise ValueError("padding must be a non-negative integer")
        if len(result) < padding:
            result = alphabet[0] * (padding - len(result)) + result

    return "-" + result if negative else result

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    # Validate inputs
    if not isinstance(number, int):
        raise TypeError(f"number must be an int, got {type(number).__name__}")
    if number < 0:
        raise ValueError("number must be non-negative")

    if not isinstance(alphabet, (list, tuple)):
        raise TypeError(f"alphabet must be a list or tuple, got {type(alphabet).__name__}")
    if len(alphabet) < 2:
        raise ValueError("alphabet must contain at least two distinct symbols")
    if len(set(alphabet)) != len(alphabet):
        raise ValueError("alphabet must contain unique symbols")
    if not all(isinstance(a, str) for a in alphabet):
        raise TypeError("alphabet elements must be strings")

    if padding is not None:
        if not isinstance(padding, int):
            raise TypeError(f"padding must be an int or None, got {type(padding).__name__}")
        if padding < 0:
            raise ValueError("padding must be non-negative")

    base = len(alphabet)
    digits: List[int] = []

    # Convert number to base-`base` digits (least significant first)
    if number == 0:
        digits.append(0)
    else:
        n = number
        while n:
            n, rem = divmod(n, base)
            digits.append(rem)

    # Most significant first
    digits.reverse()

    # Apply padding if requested
    if padding is not None and padding > len(digits):
        digits = [0] * (padding - len(digits)) + digits

    # Build the resulting string
    return ''.join(alphabet[d] for d in digits)

