    The input is assumed to have the most significant digit first.
    """
    if not alphabet:
        raise ValueError("Alphabet list must not be empty.")
    base = len(alphabet)
    if base < 2:
        raise ValueError("Alphabet must contain at least two unique symbols.")
    # Build mapping from symbol to its numeric value
    try:
        mapping = {symbol: idx for idx, symbol in enumerate(alphabet)}
    except Exception as exc:
        raise ValueError("Failed to construct alphabet mapping.") from exc

    # If the string is empty, interpret it as zero
    if not string:
        return 0

    number = 0
    for char in string:
        if char not in mapping:
            raise ValueError(f"Character '{char}' is not present in the alphabet.")
        number = number * base + mapping[char]

    return number

