def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    # Accept None or the special string "always" (case-insensitive)
    if frequency is None:
        return None
    if isinstance(frequency, str) and frequency.strip().lower() == 'always':
        return None

    if not isinstance(frequency, str):
        raise ValueError(f'Frequency must be a string, got {type(frequency).__name__}')

    freq = frequency.strip()

    # Extract the numeric part and the unit part (allow optional spaces)
    import re
    m = re.match(r'^(\d+)\s*([a-zA-Z]+)$', freq)
    if not m:
        raise ValueError(f'Invalid frequency format: {frequency!r}')

    number = int(m.group(1))
    unit = m.group(2).lower()

    # Normalise unit by removing a trailing 's' (plural)
    if unit.endswith('s'):
        unit = unit[:-1]

    # Map recognised units to datetime.timedelta arguments.
    if unit == 'minute':
        return datetime.timedelta(minutes=number)
    elif unit == 'hour':
        return datetime.timedelta(hours=number)
    elif unit == 'day':
        return datetime.timedelta(days=number)
    elif unit == 'week':
        return datetime.timedelta(weeks=number)
    elif unit == 'second':
        return datetime.timedelta(seconds=number)
    elif unit == 'month':
        # Rough estimate: 30 days per month
        return datetime.timedelta(days=30 * number)
    elif unit == 'year':
        # Rough estimate: 365 days per year
        return datetime.timedelta(days=365 * number)

    # If we reach here, the unit is not recognised
    raise ValueError(f'Unknown time unit in frequency: {unit!r}')

