                ip_obj = ipaddress.ip_address(raw_ip)
                if ip_obj.is_loopback:
                    return True
            except ValueError:
                # Not a valid IP address; skip
                continue
        else:
            # Fallback manual checks for IPv4 and IPv6 loopback
            try:
                # IPv4
                packed = socket.inet_aton(raw_ip)
                return packed[0] == 127
            except OSError:
                # Not IPv4; check for IPv6 ::1
                if raw_ip == "::1":
                    return True

    return False

def make_find_paths(find_paths):
    '''
    Given a sequence of path fragments or patterns as passed to `--find`, transform all path
    fragments into glob patterns. Pass through existing patterns untouched.

    For example, given find_paths of:

      ['foo.txt', 'pp:root/somedir']

    ... transform that into:

      ['sh:**/*foo.txt*/**', 'pp:root/somedir']
    '''
    # Normalize input to a list of strings
    if isinstance(find_paths, str):
        # If a single string is given, treat it as a single path fragment
        paths = [find_paths]
    else:
        try:
            paths = list(find_paths)
        except TypeError:
            raise TypeError(
                f"find_paths should be an iterable of strings, got {type(find_paths)!r}"
            )

    # Helper to determine if a path is already a pattern
    def is_pattern(path: str) -> bool:
        # If it contains a colon (e.g., 'pp:...'), treat it as a full pattern
        return ':' in path

    transformed = []
    for path in paths:
        if not isinstance(path, str):
            raise TypeError(
                f"Each find_path must be a string, got {type(path)!r} for path {path!r}"
            )
        if is_pattern(path):
            # Keep existing patterns untouched
            transformed.append(path)
        else:
            # Wrap the fragment into a glob pattern
            transformed.append(f'sh:**/*{path}*/**')

    return transformed

def make_find_paths(find_paths):
    """
    Given a sequence of path fragments or patterns as passed to `--find`, transform all path
    fragments into glob patterns. Pass through existing patterns untouched.

    For example, given find_paths of:

      ['foo.txt', 'pp:root/somedir']

    ... transform that into:

      ['sh:**/*foo.txt*/**', 'pp:root/somedir']
    """
    if find_paths is None:
        return []
    try:
        iterator = iter(find_paths)
    except TypeError:
        raise TypeError(f"find_paths should be an iterable, got {type(find_paths)}")

    transformed = []
    for idx, fp in enumerate(iterator):
        if not isinstance(fp, str):
            raise TypeError(f"Each find_path should be a string, item {idx} is {type(fp)}")
        # If the fragment already looks like a pattern (contains ':') we leave it unchanged
        if ':' in fp:
            transformed.append(fp)
        else:
            # Wrap the fragment into a recursive shell glob
            transformed.append(f"sh:**/*{fp}*/**")
    return transformed

def is_gitbash():
    """
    returns True if you run in a Windows gitbash

    :return: True if gitbash
    """
    try:
        # Must be running on Windows
        if os.name != 'nt':
            return False

        # Git Bash sets the environment variable OSTYPE to 'msys' or 'cygwin'
        ostype = os.getenv('OSTYPE', '')
        if ostype.lower() in ('msys', 'cygwin'):
            return True

        # Some setups may not set OSTYPE; the presence of 'sh.exe' or
        # 'git.exe' in the PATH is another hint that Git Bash is active.
        path = os.getenv('PATH', '')
        for exe in ('sh.exe', 'git.exe'):
            if any(part.lower() == exe for part in path.split(os.pathsep)):
                return True

        return False
    except Exception:
        return False

def is_gitbash():
    """
    returns True if you run in a Windows gitbash

    :return: True if gitbash
    """
    try:
        if os.name != 'nt':
            return False
        # In Git Bash, MSYSTEM is set (e.g., MINGW64) or OSTYPE starts with 'bash'
        return bool(os.getenv('MSYSTEM')) or os.getenv('OSTYPE', '').startswith('bash')
    except Exception:
        return False

