def scale(self, other=None):
    """Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    # Getter: return current scale
    if other is None:
        return getattr(self, "_scale", None)

    # Setter: ensure new_scale is numeric
    try:
        new_scale = float(other)
    except Exception as exc:
        raise TypeError("other must be a numeric value") from exc

    # Current scale must be known and non‑zero
    current_scale = getattr(self, "_scale", None)
    if current_scale is None or current_scale == 0:
        raise ValueError("Cannot rescale graph with unknown or zero current scale")

    if new_scale == 0:
        raise ValueError("New scale cannot be zero")

    # Identify the last coordinate field
    if not hasattr(self, "fields") or not self.fields:
        raise AttributeError("Graph has no coordinate fields")
    last_field = self.fields[-1]

    # Rescale the data for the last coordinate
    if hasattr(self, "data"):
        try:
            self.data[last_field] *= new_scale
        except Exception as exc:
            raise RuntimeError(f"Failed to rescale data column '{last_field}'") from exc
    else:
        # If individual attributes are used for coordinates
        if hasattr(self, last_field):
            setattr(self, last_field, getattr(self, last_field) * new_scale)

    # Rescale the errors for the same coordinate if present
    if hasattr(self, "errors"):
        errors = self.errors
        if isinstance(errors, dict) and last_field in errors:
            errors[last_field] *= new_scale
        else:
            # fallback: attribute named <field>_err
            err_name = f"{last_field}_err"
            if hasattr(self, err_name):
                setattr(self, err_name, getattr(self, err_name) * new_scale)

    # Store the new scale
    self._scale = new_scale

    return self

