def _verify(iface, candidate, tentative=False, vtype=None):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the interface using
      ``iface.providedBy`` (unless *tentative* is ``True``, in which case this
      step is skipped). This means that the candidate's class declares that it
      ``implements`` the interface, or the candidate itself declares that it
      ``provides`` the interface.

    - Making sure the candidate defines all the necessary methods.

    - Making sure the methods have the correct signature (to the
      extent possible).

    - Making sure the candidate defines all the necessary attributes.

    :return bool: Returns a true value if everything that could be
       checked passed.
    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    # Import packages lazily to keep the function self‑contained.
    import inspect
    try:
        from zope.interface import Invalid
    except Exception:
        # Fallback for environments without zope.interface
        class Invalid(ValueError):
            pass

    errors = []

    # Step 1: Check that candidate claims to provide the interface, unless tentative.
    if not tentative:
        try:
            provides = iface.providedBy(candidate)
        except Exception:
            # In case iface doesn't have providedBy (unlikely), treat as failure.
            provides = False
        if not provides:
            errors.append(f"Candidate {candidate!r} does not provide interface {iface!r}")

    # Helper functions to retrieve required methods/attributes.
    def _get_required_methods(itf):
        try:
            return itf.getRequiredMethods()
        except AttributeError:
            # Fall back: attributes that are callables on the interface
            return [name for name, value in itf.__dict__.items()
                    if callable(value) and not name.startswith('_')]

    def _get_required_attrs(itf):
        try:
            return itf.getRequiredAttributes()
        except AttributeError:
            # Fall back: interface attributes that are not callables
            return [name for name, value in itf.__dict__.items()
                    if not callable(value) and not name.startswith('_')]

    # Step 2: Ensure all required methods exist and match signature.
    for name in _get_required_methods(iface):
        # Candidate must have the method.
        if not hasattr(candidate, name):
            errors.append(f"Missing required method {name} on candidate {candidate!r}")
