    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    # Helper to produce a human‑readable class name
    def _name(obj):
        if isinstance(obj, type):
            return obj.__name__
        return type(obj).__name__

    try:
        # iface must be a class or an abstract base class
        if not isinstance(iface, type):
            raise TypeError(f"iface must be a class, got {_name(iface)}")

        # Determine the class of the candidate
        if isinstance(candidate, type):
            cand_cls = candidate
