            if tentative:
                return False
            raise TypeError(f"{cand_cls.__name__} does not subclass {iface.__name__}")

        # Inspect abstract methods defined on the interface
        abstract_methods = {
            name
            for name, member in iface.__dict__.items()
            if callable(member) and getattr(member, "__isabstractmethod__", False)
        }

        # Ensure candidate implements all abstract methods
        for method_name in abstract_methods:
            if not hasattr(cand_cls, method_name):
                if tentative:
                    return False
