    """Determine metaclass from 1+ bases and optional explicit __metaclass__."""
    # If an explicit metaclass is provided, use it directly.
    if explicit_mc is not None:
        return explicit_mc

    if not bases:
        # Default to the normal type metaclass if no bases are supplied.
        return type

    # Helper to choose a compatible metaclass between two.
    def _merge_metaclass(m1, m2):
        if issubclass(m1, m2):
            return m1
        if issubclass(m2, m1):
            return m2
        # Incompatible metaclasses raise an informative TypeError.
        raise TypeError(
            f"metaclass conflict: {m1.__name__} (derived from {m2.__name__}) "
            "is not a subclass of the other metaclass"
        )

    # Determine the most derived metaclass among all base metaclasses.
    result_meta = None
    for base in bases:
        # Skip objects that are not classes.
        if not isinstance(base, type):
            continue
        base_meta = type(base)
        if result_meta is None:
            result_meta = base_meta
        else:
            result_meta = _merge_metaclass(result_meta, base_meta)

    # Fallback to type if the result is still None (e.g., all bases were non-classes).
    return result_meta or type

