                result["subject"] = data["subject"]
            return result
    except Exception:
        # Not valid JSON; fall back to XRD XML parsing
        pass

    # If JSON parsing failed, try XML/XRD parsing
    try:
        root = etree.fromstring(document.encode("utf-8"))
    except Exception:
        return None

    # Helper for namespace handling
    ns = {}
    if root.tag.startswith("{"):
        ns_uri = root.tag[root.tag.find("{") + 1 : root.tag.find("}")]
        ns = {"xrd": ns_uri}
        link_tag = f"{{{ns_uri}}}Link"
        subject_tag = f"{{{ns_uri}}}Subject"
    else:
        link_tag = "Link"
        subject_tag = "Subject"

    result = {}
    for link in root.findall(f".//{link_tag}", ns or None):
        rel = link.attrib.get("rel")
        href = link.attrib.get("href")
        if rel and href:
            result[rel] = href

    # Extract subject if present
    subject_el = root.find(subject_tag, ns or None)
    if subject_el is not None and subject_el.text:
        result["subject"] = subject_el.text

    return result if result else None

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        host = handle.split("@")[1]
    except Exception:
        return None
    url = f"http://{host}/.well-known/webfinger?resource=acct:{handle}"
    try:
        from urllib.request import urlopen
        from urllib.error import URLError, HTTPError
        with urlopen(url, timeout=5) as response:
            content = response.read()
            return content.decode("utf-8", errors="replace")
    except (URLError, HTTPError, Exception):
        return None

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        if '@' not in handle:
            return None
        host = handle.split('@', 1)[1]
        # URL-encode the handle
        try:
            from urllib.parse import quote
        except ImportError:
            # Python 2 fallback
            from urllib import quote
        webfinger_uri = f"https://{host}/.well-known/webfinger?resource=acct:{quote(handle)}"
        with urllib2.urlopen(webfinger_uri) as response:
            content = response.read()
            # Return decoded string if possible, otherwise raw bytes
            try:
                return content.decode('utf-8')
            except Exception:
                return content
    except Exception:
        return None

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """Try to retrieve an RFC7033 webfinger document. Does not raise if it fails."""
    try:
        _, host = handle.split("@", 1)
    except Exception:
        # Handle not in expected "user@host" format
        return None

    try:
        # Construct the webfinger URL
        resource = "acct:%s" % quote(handle)
        path = "/.well-known/webfinger?resource=%s" % resource
        url = "https://%s%s" % (host, path)

        # Attempt to fetch via HTTPS first
        try:
            with closing(urllib2.urlopen(url)) as page:
                return page.read()
        except urllib2.URLError:
            # Fallback to HTTP if HTTPS fails
            url = "http://%s%s" % (host, path)
            with closing(urllib2.urlopen(url)) as page:
                return page.read()
    except Exception:
        # Any other failure (e.g., network, parsing) should be silent
        return None

