def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.post``.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """
    # Log the send attempt
    try:
        logger.debug(
            "send_document: url=%s, data=%s, timeout=%s, method=%s",
            url, data, timeout, method
        )
    except NameError:
        # logger may not exist in all contexts; ignore
        pass

    # Prepare headers, respecting any provided in kwargs
    headers = kwargs.pop("headers", {})
    if not isinstance(headers, dict):
        headers = {}

    # Add any additional kwargs
    request_kwargs = {"data": data, "timeout": timeout, "headers": headers}
    request_kwargs.update(kwargs)

    try:
        # Use the specified method; default is POST
        if method.lower() == "post":
            response = requests.post(url, *args, **request_kwargs)
        else:
            # Generic HTTP method handling
            response = requests.request(method.upper(), url, *args, **request_kwargs)

        # Log the response status
        try:
            logger.debug("send_document: response status code %s", response.status_code)
        except NameError:
            pass

        return response.status_code, None
    except requests.exceptions.RequestException as ex:
        # Log the exception
        try:
            logger.debug("send_document: exception %s", ex)
        except NameError:
            pass
        return None, ex

def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.post``.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """
    # Normalize method name
    method = method.lower()
    if method not in ("post", "get", "put", "delete", "patch"):
        raise ValueError(f"Unsupported method '{method}'. Supported methods: POST, GET, PUT, DELETE, PATCH")

    # Choose the appropriate requests function
    if method == "post":
        request_func = requests.post
    elif method == "get":
        request_func = requests.get
    elif method == "put":
        request_func = requests.put
    elif method == "delete":
        request_func = requests.delete
    elif method == "patch":
        request_func = requests.patch

    # Merge user-provided headers if any, and add defaults
    headers = kwargs.get("headers", {}).copy()
    # Avoid mutating the original kwargs
    kwargs = dict(kwargs)
    if headers is None:
        headers = {}

    # Ensure we use the provided timeout and data in the request
    kwargs.update({
        "data": data,
        "timeout": timeout,
        "headers": headers,
    })

    try:
        response = request_func(url, *args, **kwargs)
        return response.status_code, None
    except RequestException as ex:
        return None, ex
    except Exception as ex:  # Catch unexpected exceptions to keep the return signature
        return None, ex

def dict_insert(dic, val, key, *keys):
    """insert a value of a nested key into a dictionary

    to insert value for a nested key, all ancestor keys should be given as
    method's arguments

    example:
      dict_insert({}, 'val', 'key1.key2'.split('.'))

    :param dic: a dictionary object to insert the nested key value into
    :param val: a value to insert to the given dictionary
    :param key: first key in a chain of key that will store the value
    :param keys: sub keys in the keys chain
    """
    if not isinstance(dic, dict):
        raise TypeError("dic must be a dictionary")
    # Determine the full key chain.
    if len(keys) == 0 and isinstance(key, (list, tuple)):
        chain = key
    else:
        chain = (key, *keys)
    if not chain:
        raise ValueError("no keys provided for insertion")
    current = dic
    for part in chain[:-1]:
        if not isinstance(part, (str, int)):
            raise TypeError("all keys must be hashable strings or integers")
        if part not in current or not isinstance(current[part], dict):
            current[part] = {}
        current = current[part]
    last_key = chain[-1]
    if not isinstance(last_key, (str, int)):
        raise TypeError("last key must be a hashable string or integer")
    current[last_key] = val

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    try:
        # Normalize input to an iterable of directories
        dirs = [settings_dirs] if isinstance(settings_dirs, (str, bytes)) else list(settings_dirs)
        result = []
        for directory in dirs:
            if not os.path.isdir(directory):
                continue
            for fname in os.listdir(directory):
                full_path = os.path.join(directory, fname)
                if not os.path.isfile(full_path):
                    continue
                if spec_option:
                    if fname.endswith(spec_option):
                        result.append(full_path)
                else:
                    result.append(full_path)
        return sorted(result)
    except Exception:
        return []

def list_of_file_names(settings_dirs, spec_option):
