def list_of_file_names(settings_dirs, spec_option):
    """Return a sorted list of fully qualified file names from the given
    directories that match the specified file suffix(es).

    Parameters
    ----------
    settings_dirs : str or Iterable[str]
        Path or collection of paths to search for files.
    spec_option : str or Iterable[str]
        File suffix(es) to match. If a single string is provided only that
        suffix will be used. If an iterable is provided each element is
        treated as a suffix. Comparison is case-sensitive.

    Returns
    -------
    list
        Sorted list of matched file paths. If no files are found an empty
        list is returned.
    """
    # Normalise settings_dirs to an iterable of strings
    if isinstance(settings_dirs, (str, bytes)):
        dirs = [settings_dirs]
    else:
        try:
            dirs = [d for d in settings_dirs if isinstance(d, (str, bytes))]
        except TypeError:
            dirs = []

    # Normalise spec_option to a tuple of suffixes
    if isinstance(spec_option, (str, bytes)):
        suffixes = (spec_option,)
    else:
        try:
            suffixes = tuple(spec_option)
        except TypeError:
            suffixes = ()
    if not suffixes:
        return []

    result = []
    for d in dirs:
        try:
            for fname in os.listdir(d):
                if any(fname.endswith(s) for s in suffixes):
                    result.append(os.path.join(d, fname))
        except OSError:
            # Skip directories that cannot be accessed
            continue
    return sorted(result)

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type"""
    try:
        dirs = [settings_dirs] if isinstance(settings_dirs, str) else list(settings_dirs)
    except Exception:
        dirs = []

    filenames = []
    for dir_path in dirs:
        try:
            if not os.path.isdir(dir_path):
                continue
            for entry in os.listdir(dir_path):
                if spec_option:
                    if isinstance(spec_option, str):
                        if spec_option.startswith('.'):
                            if not entry.endswith(spec_option):
                                continue
                        else:
                            if spec_option not in entry:
                                continue
                    else:
                        continue
                filenames.append(os.path.join(dir_path, entry))
        except OSError:
            continue
    return sorted(filenames)

def list_of_file_names(settings_dirs, spec_option):
    """
    Return a list of fully qualified file names within the provided directories
    that satisfy the filtering specified by ``spec_option``.

    Parameters
    ----------
    settings_dirs : str or Iterable[str]
        One or more directory paths to search.
    spec_option : str, Iterable[str] or None
        A file extension (e.g. ``'.ini'``), a pattern containing glob wildcards
        (e.g. ``'*.conf'``), or a collection of such patterns. If ``None``,
        all files are returned.

    Returns
    -------
    list[str]
        Sorted list of absolute file paths that match the criteria.
    """
    import os
    from fnmatch import fnmatch

    try:
        # Normalise directory list
        dirs = [settings_dirs] if isinstance(settings_dirs, str) else list(settings_dirs)

        # Normalise pattern list
        if spec_option is None:
            patterns = [None]
        else:
            patterns = list(spec_option) if isinstance(spec_option, (list, tuple)) else [spec_option]

        matched_files = []

        for directory in dirs:
            if not isinstance(directory, str):
                continue
            if not os.path.isdir(directory):
                continue
            try:
                for entry in os.listdir(directory):
                    full_path = os.path.join(directory, entry)
                    if os.path.isfile(full_path):
                        if patterns == [None]:
                            matched_files.append(os.path.abspath(full_path))
                        else:
                            for pat in patterns:
                                if pat and fnmatch(entry, pat):
                                    matched_files.append(os.path.abspath(full_path))
                                    break
            except (OSError, PermissionError):
                # Skip directories that cannot be accessed
                continue

        return sorted(set(matched_files))
    except Exception:
        # In any unexpected situation, return an empty list
        return []

