def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    def _deep_merge(dest, src):
        for key, val in src.items():
            if key in dest and isinstance(dest[key], dict) and isinstance(val, dict):
                _deep_merge(dest[key], val)
            else:
                dest[key] = val

    def _resolve_node(name, visited):
        if name not in parser_dict:
            raise KeyError(f"Included group '{name}' not found in parser definitions.")
        node = parser_dict[name]
        # Create a shallow copy to avoid mutating the original until fully merged
        node_copy = dict(node)
        if 'include' in node_copy:
            inc = node_copy.pop('include')
            inc_names = inc if isinstance(inc, (list, tuple)) else [inc]
            merged = {}
            for inc_name in inc_names:
                if inc_name in visited:
                    cycle = ' -> '.join(list(visited) + [inc_name])
                    raise RuntimeError(f"Circular include detected: {cycle}")
                inc_node = _resolve_node(inc_name, visited | {inc_name})
                _deep_merge(merged, inc_node)
            _deep_merge(merged, node_copy)
            return merged
        return node_copy

    # Resolve each parser entry, handling nested includes.
    for key in list(parser_dict.keys()):
        resolved = _resolve_node(key, {key})
        parser_dict[key] = resolved

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    include_spec = parser_dict.pop('include', None)
    if include_spec is None:
        return parser_dict
    if not isinstance(include_spec, dict):
        raise ValueError('include directive must be a mapping')
    for new_key, existing_key in include_spec.items():
        if existing_key not in getattr(self, '_groups', {}):
            raise KeyError(f"Included group '{existing_key}' not found")
        # Merge the group definition into the parser dictionary.
        # A deep copy is used to avoid side‑effects on the original group spec.
        parser_dict[new_key] = copy.deepcopy(self._groups[existing_key])
    return parser_dict

def _include_groups(self, parser_dict):
        """Resolves the `include` dict directive in the spec files."""
        # Return a new dict to avoid mutating the caller's data.
        def _resolve(node):
            if not isinstance(node, dict):
                return node  # Base case: not a dict, return as-is.
            result = {}
            for key, value in node.items():
                if key == 'include':
                    # The `include` key can be a single dict or a list of dicts.
                    inc_items = value
                    if isinstance(inc_items, dict):
                        inc_items = [inc_items]
                    elif isinstance(inc_items, list):
                        pass
                    else:
                        raise ValueError(f\"Inclusion item for key 'include' must be a dict or list, got {type(inc_items)}\")
                    for inc_dict in inc_items:
                        if not isinstance(inc_dict, dict):
                            raise ValueError(\"Each included item must be a dict.\")
                        # Recursively resolve nested includes.
                        resolved_inc = _resolve(inc_dict)
                        # Merge into result; later keys override earlier ones.
                        result.update(resolved_inc)
                else:
                    # Recursively resolve nested structures.
                    result[key] = _resolve(value)
            return result

        try:
            resolved = _resolve(parser_dict)
            return resolved
        except Exception as e:
            # If something goes wrong, provide context for easier debugging.
            raise RuntimeError(f\"Failed to resolve include groups for parser_dict {parser_dict}: {e}\") from e

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files.

    Any spec dictionary may contain an ``include`` key whose value is a
    string or iterable of keys referring to other spec dictionaries in the
    same ``parser_dict``.  This method expands those directives by
    merging the referenced spec into the current one.  The merge is
    performed shallowly: keys present in the current spec override those
    in the included spec.  Nested dictionaries are merged recursively.
    Circular includes raise a ``RuntimeError``.  Unknown include keys
    raise a ``KeyError``.  The original dictionary is modified in-place.
    """
    def _merge(target, source):
        """Recursively merge ``source`` into ``target``."""
        for key, value in source.items():
            # Skip the 'include' directive if it sneaks into nested specs
            if key == 'include':
                continue
            if isinstance(value, dict) and isinstance(target.get(key), dict):
                _merge(target[key], value)
            else:
                target[key] = value

    processed = set()

    def _process(key, seen):
        if key in processed:
            return
        if key in seen:
            cycle = " -> ".join(list(seen) + [key])
            raise RuntimeError(f"Circular include detected: {cycle}")
        spec = parser_dict.get(key)
        if spec is None:
            raise KeyError(f"Included parser '{key}' not found in parser_dict")
        seen = seen | {key}
        includes = spec.pop('include', [])
        # Normalize includes to a list of keys
        if isinstance(includes, (str, int)):
            includes = [includes]
        elif not isinstance(includes, (list, tuple, set)):
            raise TypeError(f"Include directive for '{key}' must be a string "
                            f"or an iterable, got {type(includes).__name__}")
        for inc in includes:
            _process(inc, seen)
            _merge(spec, parser_dict[inc])
        processed.add(key)

    for top_key in list(parser_dict.keys()):
        _process(top_key, set())

def _include_groups(self, parser_dict):
        """Resolves the include dict directive in the spec files."""
        # Iterate over a copy of the keys to allow modifications during iteration
        for key, value in list(parser_dict.items()):
            # If the value is a dictionary and contains an 'include' directive
            if isinstance(value, dict) and 'include' in value:
                include_directive = value.pop('include')
                # The include directive can be a mapping (name -> path) or a single path string
                try:
                    if isinstance(include_directive, dict):
                        # Merge each included spec into the current dictionary
                        for inc_name, inc_path in include_directive.items():
                            # Attempt to read the spec file and parse it as JSON or YAML
                            try:
                                import json
                                with open(inc_path, 'r') as f:
                                    inc_spec = json.load(f)
                                    value[inc_name] = inc_spec
                            except Exception:
                                try:
                                    import yaml
                                    with open(inc_path, 'r') as f:
                                        inc_spec = yaml.safe_load(f)
                                        value[inc_name] = inc_spec
                                except Exception:
                                    # If parsing fails, skip this include
                                    pass
                    else:
                        # Single include path – replace the current entry entirely
                        try:
                            import json
                            with open(include_directive, 'r') as f:
                                inc_spec = json.load(f)
                                parser_dict[key] = inc_spec
                        except Exception:
                            try:
                                import yaml
                                with open(include_directive, 'r') as f:
                                    inc_spec = yaml.safe_load(f)
                                    parser_dict[key] = inc_spec
                            except Exception:
                                pass
                except Exception:
                    # Silently ignore any unexpected errors during include handling
                    pass
            # Recursively resolve includes in nested dictionaries
            if isinstance(value, dict):
                self._include_groups(value)

