    # Start with defaults from the default spec.
    resolved = {}
    if hasattr(self, "_default_spec") and self._default_spec is not None:
        try:
            # If the default spec is dict‑like, update directly.
            resolved.update(self._default_spec)
        except Exception:
            try:
                # Fallback: convert to a dict if possible.
                resolved.update(dict(self._default_spec))
            except Exception:
                # If something goes wrong, ignore this source.
                pass

    # Merge the current spec values, overriding defaults.
    if hasattr(self, "spec") and self.spec is not None:
        try:
            resolved.update(self.spec)
