    defaults = {}
    # iterate over all arguments defined in the scheme
    for arg in getattr(self, "args", []):
        # Attempt to get an explicit value from the argument's spec
        try:
            spec = getattr(arg, "spec", None)
            if spec is not None:
                explicit_val = getattr(spec, "value", None)
                if explicit_val is not None:
                    defaults[arg.name] = explicit_val
                    continue
        except Exception:
            # ignore any issue retrieving from spec
            pass

        # Fall back to the argument's own default value if available
        if hasattr(arg, "default") and not isinstance(arg.default, NoDefault):
            defaults[arg.name] = arg.default

        # If the argument is a dictionary type with its own scheme,
        # recursively build defaults for that nested scheme.
        if isinstance(arg, DictOption):
            scheme = getattr(arg, "scheme", None)
            if scheme and hasattr(scheme, "build_defaults"):
                nested = scheme.build_defaults()
                if nested:
                    defaults[arg.name] = nested
    return defaults

