                f"argument at position {idx} ({num_val}) below minimum {min_}"
            )
        if max_ is not None and num_val > max_:
            raise ValueError(
                f"argument at position {idx} ({num_val}) above maximum {max_}"
            )

    return args

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    :return: ``args`` if all values are within the configured bounds.
    :raise AttributeError: If ``self`` does not define ``min_`` and/or ``max_`` attributes.
    :raise ValueError: If bounds are improperly defined or any argument falls outside the allowed range.
    :raise TypeError: If an argument is not comparable with the bounds.
    """
    # Ensure the object has the necessary bounds
    if not hasattr(self, "min_") or not hasattr(self, "max_"):
        raise AttributeError("Object must define 'min_' and 'max_' attributes for validation.")

    min_val = getattr(self, "min_")
    max_val = getattr(self, "max_")

    # At least one bound must be defined
    if min_val is None and max_val is None:
        raise ValueError("At least one of 'min_' or 'max_' must be set.")

    # Validate bound ordering
    if min_val is not None and max_val is not None and min_val > max_val:
        raise ValueError("Maximum bound must be greater than or equal to the minimum bound.")

    # Iterate over the provided arguments and check each
    for index, val in enumerate(args):
        if val is None:
            # Skip validation for ``None`` values
            continue
        try:
            if min_val is not None and val < min_val:
                raise ValueError(
                    f"Argument at position {index} with value {val} is below the minimum {min_val}"
                )
            if max_val is not None and val > max_val:
                raise ValueError(
                    f"Argument at position {index} with value {val} exceeds the maximum {max_val}"
                )
        except TypeError as exc:
            raise TypeError(
                f"Argument at position {index} with value {val} is not comparable with the bounds"
            ) from exc

    return args

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    :return: args if all values are within bounds.
    :raise ValueError: If bounds are not defined, or any value is outside bounds.
    :raise TypeError: If args cannot be iterated or contains non-numeric values.
    """
    # Retrieve bounds from the instance
    min_val = getattr(self, "min_", None)
    max_val = getattr(self, "max_", None)

    if min_val is None and max_val is None:
        raise ValueError("Minimum and/or maximum values must be defined in the instance")

    if min_val is not None and max_val is not None and min_val > max_val:
        raise ValueError("Maximum value must be greater than or equal to minimum value")

    # If args is not iterable (and not a string), wrap it in a tuple
    if isinstance(args, str) or not hasattr(args, "__iter__"):
        iterable = (args,)
    else:
        iterable = args

    # Validate each element
    for idx, value in enumerate(iterable):
        # Ensure numeric
        if not isinstance(value, (int, float)):
            raise TypeError(f"Argument at position {idx} ({value!r}) is not numeric")
        if min_val is not None and value < min_val:
            raise ValueError(f"Argument {value} at position {idx} is less than minimum {min_val}")
        if max_val is not None and value > max_val:
            raise ValueError(f"Argument {value} at position {idx} is greater than maximum {max_val}")

    return args

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Ensure args is iterable
    if args is None or not hasattr(args, "__iter__"):
        raise TypeError("args must be an iterable")

    for idx, item in enumerate(args):
        # Accept either a dict with keys or a tuple/list of length 3
        if isinstance(item, dict):
            value = item.get("value")
            min_ = item.get("min")
            max_ = item.get("max")
        elif isinstance(item, (tuple, list)) and len(item) == 3:
            value, min_, max_ = item
        else:
            raise ValueError(f"Argument #{idx} is not in a supported format (dict or (value, min, max))")

        # All three components must be present
        if value is None or min_ is None or max_ is None:
            raise ValueError(f"Argument #{idx} must contain 'value', 'min', and 'max'")

        # Validate that min is not greater than max
        if min_ > max_:
            raise ValueError(f"Argument #{idx} has min greater than max ({min_} > {max_})")

        # Check value range
        if not (min_ <= value <= max_):
            raise ValueError(f"Argument #{idx} value {value} is outside the range [{min_}, {max_}]")

    return args

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.  Accepts a mapping of argument
                 names to dictionaries that must contain a 'value' key
                 and may contain 'min' and/or 'max' keys.  Alternatively,
                 a single dictionary with 'value', 'min', and/or 'max' can
                 be supplied or a list/tuple of such dictionaries.

    :return: ``args`` unchanged if validation succeeds.

    :raise TypeError: If ``args`` is not a supported structure.
    :raise ValueError: If any value falls outside the specified bounds.
    """
    def _check(value, min_val, max_val, name):
        if min_val is not None and value < min_val:
            raise ValueError(f"{name!r} value {value} is less than minimum {min_val}")
        if max_val is not None and value > max_val:
            raise ValueError(f"{name!r} value {value} is greater than maximum {max_val}")

    # Handle a single mapping with 'value' key
    if isinstance(args, dict):
        # If 'value' key exists in top-level dict, the dict may be a single argument
        if 'value' in args:
            _check(args['value'], args.get('min'), args.get('max'), 'argument')
        else:
            # Otherwise treat each key as an argument name with a sub-dict
            for key, sub in args.items():
                if not isinstance(sub, dict):
                    raise TypeError(f"Argument {key!r} must be a dict containing a 'value' key")
                if 'value' not in sub:
                    raise KeyError(f"Argument {key!r} missing required 'value' key")
                _check(sub['value'], sub.get('min'), sub.get('max'), key)
    elif isinstance(args, (list, tuple)):
        # Treat list/tuple as a collection of argument dicts
        for idx, item in enumerate(args):
            if not isinstance(item, dict):
                raise TypeError(f"Item {idx!r} in list must be a dict with a 'value' key")
            if 'value' not in item:
                raise KeyError(f"Item {idx!r} missing required 'value' key")
            _check(item['value'], item.get('min'), item.get('max'), f"item {idx}")
    else:
        raise TypeError("args must be a dict or a list/tuple of dicts")

    return args

def create_complex_argumet_type(self, subcommand, type_name, option_name, spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    # Basic validation of inputs
    if not isinstance(subcommand, str):
        raise TypeError(f"subcommand must be a string, got {type(subcommand).__name__}")
    if not isinstance(type_name, str):
        raise TypeError(f"type_name must be a string, got {type(type_name).__name__}")
    if not isinstance(option_name, str):
        raise TypeError(f"option_name must be a string, got {type(option_name).__name__}")
    if not isinstance(spec_option, dict):
        raise TypeError(f"spec_option must be a dict, got {type(spec_option).__name__}")

    # Attempt to construct the complex type using a factory if provided
    try:
        factory = spec_option.get('factory')
        if factory is not None:
            # Resolve the factory if it is specified as a string
            if isinstance(factory, str):
                factory = self.load_name(factory)
            # Separate positional and keyword arguments for the factory
            args = spec_option.get('args', [])
            kwargs = spec_option.get('kwargs', {})
            complex_type = factory(*args, **kwargs)
        else:
            # No factory, construct a simple namespace or dictionary
            complex_type = type(
                type_name,
                (object,),
                {
                    'subcommand': subcommand,
                    'option_name': option_name,
                    **spec_option
                }
            )()
    except Exception as exc:
        # Wrap any exception in a more descriptive error
        raise ValueError(
            f"Failed to create complex type '{type_name}' for subcommand '{subcommand}': {exc}"
        ) from exc

    return complex_type

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                    spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    try:
        # Basic validation
        if not isinstance(subcommand, str) or not subcommand.strip():
            raise ValueError("subcommand must be a non-empty string")
        if not isinstance(type_name, str) or not type_name.strip():
            raise ValueError("type_name must be a non-empty string")
        if not isinstance(option_name, str) or not option_name.strip():
            raise ValueError("option_name must be a non-empty string")
        if not isinstance(spec_option, dict):
            raise TypeError("spec_option must be a dict")

        # Build the core attributes for the complex argument
        attrs = {
            "subcommand": subcommand,
            "type_name": type_name,
            "option_name": option_name,
        }

        # Merge user supplied specifications, avoiding overwriting the mandatory attributes
        for key, value in spec_option.items():
            if key not in attrs:
                attrs[key] = value

        # Force a callable type; default to str if not provided
        if "type" not in attrs or not callable(attrs["type"]):
            attrs["type"] = str

        # Simple container for the complex argument
        class ComplexArgumentType:
            def __init__(self, **kwargs):
                for k, v in kwargs.items():
                    setattr(self, k, v)

            def __repr__(self):
                return f"<ComplexArgumentType {self.__dict__}>"

        return ComplexArgumentType(**attrs)

    except Exception as exc:
        raise ValueError(f"Failed to create complex argument type: {exc}") from exc

def create_complex_argumet_type(self, subcommand, type_name, option_name, spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    # Basic sanity checks
    if not isinstance(subcommand, str):
        raise TypeError("subcommand must be a string")
    if not isinstance(type_name, str):
        raise TypeError("type_name must be a string")
    if not isinstance(option_name, str):
        raise TypeError("option_name must be a string")
    if not isinstance(spec_option, dict):
        raise TypeError("spec_option must be a dict")

    # If the spec explicitly defines a type we can use load_name
    if "__type__" in spec_option:
        type_fqdn = spec_option.pop("__type__")
        type_constructor = self.load_name(type_fqdn)
        try:
            return type_constructor(**spec_option)
        except Exception as exc:
            raise ValueError(f"Failed to construct type {type_name} for option {option_name}: {exc}") from exc

    # Default behaviour: create a simple conversion and validation function
    base_type = spec_option.get("type", str)
    if isinstance(base_type, str):
        try:
            base_type = getattr(__builtins__, base_type)
        except AttributeError:
            base_type = self.load_name(base_type)

    def parse_value(value):
        try:
            val = base_type(value)
        except Exception as exc:
            raise argparse.ArgumentTypeError(f"Invalid value for {option_name}: {exc}") from exc

        # Choice validation
        choices = spec_option.get("choices")
        if choices and val not in choices:
            raise argparse.ArgumentTypeError(
                f"{option_name} must be one of {choices}, got {val}"
            )

        # Custom validation hook
        validate = spec_option.get("validate")
        if validate:
            if isinstance(validate, str):
                validate = self.load_name(validate)
            if not validate(val):
                raise argparse.ArgumentType

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                 spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    # Basic input validation
    if not isinstance(subcommand, str) or not subcommand:
        raise ValueError("subcommand must be a non-empty string")
    if not isinstance(type_name, str) or not type_name:
        raise ValueError("type_name must be a non-empty string")
    if not isinstance(option_name, str) or not option_name:
        raise ValueError("option_name must be a non-empty string")

    if spec_option is None:
        spec_option = {}
    if not isinstance(spec_option, dict):
        raise ValueError("spec_option must be a dictionary")

    # Construct the complex type representation
    complex_type = {
        "subcommand": subcommand,
        "type_name": type_name,
        "option_name": option_name,
        **spec_option
    }

    # Optionally, if the system expects a class, create one dynamically
    try:
        cls_name = f"{type_name.capitalize()}Arg"
        ComplexArgClass = type(
            cls_name,
            (object,),
            # Initialize the instance with the values
            {"__init__": lambda self, **kwargs: self.__dict__.update(kwargs)}
        )
        instance = ComplexArgClass(**complex_type)
        return instance
    except Exception as e:
        # Fallback: return the dictionary if class creation fails
        return complex_type

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    # Normalise args to a dictionary
    if args is None:
        args_dict = {}
    elif isinstance(args, dict):
        args_dict = dict(args)
    elif isinstance(args, (list, tuple)):
        args_dict = {}
        for item in args:
            if isinstance(item, str):
                # allow flag style or key=value
                if "=" in item:
                    key, val = item.split("=", 1)
                    args_dict[key] = val
                else:
                    args_dict[item] = True
            elif isinstance(item, (list, tuple)) and len(item) == 2:
                args_dict[item[0]] = item[1]
            else:
                continue  # ignore malformed entry
    else:
        raise TypeError("Expected args to be a dict or list/tuple of arguments")

    # Determine which keys are considered control arguments.
    # The list of control keys may be defined on the instance. If not,
    # we fall back to an empty set.
    control_keys = getattr(self, "CONTROL_ARGS", set())

    control_args = {}
    nested_args = {}

    for key, value in args_dict.items():
        if key in control_keys:
            control_args[key] = value
        else:
            nested_args[key] = value

    # Return flat dicts for control and nested arguments
    return control_args, nested_args

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    # Ensure we have a dictionary of arguments; if args is a list of
    # tuples/lists we convert it into a dict.
    if isinstance(args, dict):
        arg_dict = args
    else:
        try:
            arg_dict = dict(args)
        except Exception:
            # If conversion fails, we return empty dicts
            LOG.warning("Unable to parse args into a dictionary: %s", args)
            return {}, {}
    # Define known control keys – these control IR behaviour.
    # The list can be extended as needed.
    CONTROL_KEYS = {
        "login",
        "destroy",
        "debug",
        "matrix",
        "list",
        "quiet",
        # add any other IR specific flags here
    }
    control_args = {}
    nested_args = {}
    for key, value in arg_dict.items():
        if key in CONTROL_KEYS:
            control_args[key] = value
        else:
            nested_args[key] = value
    return control_args, nested_args

def get_nested_custom_and_control_args(self, args):
    """
    Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    # Validate input
    if args is None:
        return {}, {}
    # Allow either a dict or an iterable of key=value strings
    if isinstance(args, dict):
        items = args.items()
    else:
        try:
            items = (item.split("=", 1) for item in args if isinstance(item, str) and "=" in item)
        except Exception as exc:
            raise ValueError("args must be a dict or an iterable of 'key=value' strings") from exc

    control_args = {}
    nested_args = {}

    for key, value in items:
        if key is None:
            continue
        key_str = str(key).strip()
        value_str = str(value).strip()

        # Detect control arguments by a common prefix
        if key_str.startswith("control."):
            # store without the prefix for consistency
            cleaned = key_str[len("control."):]
            control_args[cleaned] = value_str
        elif key_str.startswith("custom."):
            # custom arguments override nested ones
            cleaned = key_str[len("custom."):]
            nested_args[cleaned] = value_str
        else:
            nested_args[key_str] = value_str

    return control_args, nested_args

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dict")
    if extra_vars is None:
        return vars_dict
    if not isinstance(extra_vars, list):
        raise TypeError("extra_vars must be a list")
    for extra in extra_vars:
        if isinstance(extra, dict):
            vars_dict.update(extra)
        else:
            raise TypeError("Each element of extra_vars must be a dict")
    return vars_dict

def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars
        :return: Updated dictionary
        """
        if vars_dict is None:
            vars_dict = {}
        if not isinstance(vars_dict, dict):
            raise ValueError("vars_dict must be a dictionary")
        if not extra_vars:
            return vars_dict
        # Accept a single dict or a list/tuple of dicts
        if isinstance(extra_vars, dict):
            extra_vars = [extra_vars]
        elif not hasattr(extra_vars, "__iter__"):
            raise ValueError("extra_vars must be a dict or an iterable of dicts")
        for item in extra_vars:
            if not isinstance(item, dict):
                raise ValueError("Each item in extra_vars must be a dictionary")
            vars_dict.update(item)
        return vars_dict

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dictionary")
    if not extra_vars:
        return vars_dict
    # Accept a single dict as a shorthand for a list of one dict
    if isinstance(extra_vars, dict):
        extra_vars = [extra_vars]
    if not isinstance(extra_vars, (list, tuple)):
        raise TypeError("extra_vars must be a list or a dictionary")
    try:
        for extra in extra_vars:
            if isinstance(extra, dict):
                vars_dict.update(extra)
            else:
                raise TypeError("Each item in extra_vars must be a dictionary")
    except Exception as exc:
        raise exc
    return vars_dict

def merge_extra_vars(vars_dict, extra_vars=None):
    """
    Extend ``vars_dict`` with ``extra-vars``.

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    :return: The updated dictionary
    """
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dictionary")

    if extra_vars is None:
        return vars_dict

    if not isinstance(extra_vars, list):
        raise TypeError("extra_vars must be a list")

    for entry in extra_vars:
        if isinstance(entry, dict):
            vars_dict.update(entry)
        else:
            # Ignore non-dict entries; they cannot be merged
            continue

    return vars_dict

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    # Validate vars_dict
    if not isinstance(vars_dict, dict):
        raise ValueError("vars_dict must be a dictionary")

    # If no extra vars provided, nothing to merge
    if extra_vars is None:
        return vars_dict

    # If extra_vars is a single dict, merge it directly
    if isinstance(extra_vars, dict):
        vars_dict.update(extra_vars)
        return vars_dict

    # If extra_vars is an iterable of items
    try:
        for item in extra_vars:
            if isinstance(item, dict):
                vars_dict.update(item)
            elif isinstance(item, (list, tuple)) and len(item) == 2:
                key, value = item
                vars_dict[key] = value
            else:
                raise ValueError(
                    "Each element in extra_vars must be a dict or a key-value pair"
                )
    except TypeError:
        raise ValueError("extra_vars must be a dict or an iterable of dicts/key-value pairs")

    return vars_dict

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """
    Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level (int 0-5, None defaults to 1)
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    # build verbosity flag
    if verbose is None:
        verb_flag = "-v"              # default single v
    else:
        # Clamp verbosity to 0-5
        level = max(0, min(int(verbose), 5))
        verb_flag = "-"+("v"*level)

    # base command
    cmd = ["ansible-playbook", verb_flag, playbook_path]

    # add ansible-playbook arguments
    if ansible_args:
        for key, value in ansible_args.items():
            # normalise key to '--key'
            if not key.startswith("--"):
                key_arg = "--" + key.lstrip("-")
            else:
                key_arg = key
            # bool flag
            if isinstance(value, bool):
                if value:
                    cmd.append(key_arg)
                # skip adding value if False
            else:
                cmd.extend([key_arg, str(value)])

    # add extra vars
    if extra_vars:
        import json
        try:
            extra_json = json.dumps(extra_vars)
        except (TypeError, ValueError):
            extra_json = str(extra_vars)
        cmd.extend(["--extra-vars", extra_json])

    # execute
    import subprocess
    try:
        output = subprocess.check_output(
            cmd, encoding="utf-8", stderr=subprocess.STDOUT
        )
    except subprocess.CalledProcessError as exc:
        raise RuntimeError(
            "Ansible playbook failed: %s\nOutput: %s" % (exc.returncode, exc.output)
        ) from exc
    return output

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    # Validate playbook path
    if not os.path.isfile(playbook_path):
        raise FileNotFoundError(f"Playbook not found: {playbook_path}")

    # Prepare command
    command = ["ansible-playbook"]

    # Verbosity
    if verbose is not None:
        if isinstance(verbose, int) and verbose > 0:
            command.append("-" + "v" * verbose)
    else:
        if logger.isEnabledFor(logging.DEBUG):
            command.append("-vvvv")
        else:
            command.append("-v")

    # Extra vars
    if extra_vars:
        if isinstance(extra_vars, dict):
            ev_str = json.dumps(extra_vars)
        else:
            ev_str = str(extra_vars)
        command.extend(["--extra-vars", ev_str])

    # Additional ansible arguments
    if ansible_args:
        for key, val in ansible_args.items():
            # Ensure key starts with a dash
            if not key.startswith("-"):
                key = f"-{key.lstrip('-')}"
            command.append(key)
            if val is not None:
                command.append(str(val))

    # Append the playbook path
    command.append(playbook_path)

    logger.debug("Executing ansible-playbook command: %s", " ".join(command))

    try:
        p = subprocess.Popen(
            command,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            env=getattr(ir_workspace, "env", os.environ.copy()),
        )
        stdout, stderr = p.communicate()
        output = stdout.decode() + stderr.decode()

        if p.returncode != 0:
            raise RuntimeError(
                f"Ansible playbook failed with return code {p.returncode}.\n"
                f"Command: {' '.join(command)}\n"
                f"Output:\n{output}"
            )
        return output
    except OSError as exc:
        raise RuntimeError(f"Failed to execute ansible-playbook: {exc}") from exc

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """
    Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    # Basic validation
    if not playbook_path:
        raise ValueError("playbook_path must be provided")

    # Resolve path relative to workspace if not absolute
    if not os.path.isabs(playbook_path):
        playbook_path = os.path.join(ir_workspace.path, playbook_path)
    if not os.path.exists(playbook_path):
        raise FileNotFoundError(f"Playbook not found: {playbook_path}")

    command = ["ansible-playbook"]

    # Add verbosity flag(s)
    if verbose:
        try:
            lvl = int(verbose)
            if lvl < 0:
                lvl = 0
        except (TypeError, ValueError):
            lvl = 1
        command.append("-v" * lvl)

    # Add extra ansible-playbook arguments
    if ansible_args:
        for opt, val in ansible_args.items():
            if isinstance(val, bool):
                if val:
                    command.append(f"--{opt}")
            elif isinstance(val, (list, tuple)):
                command.append(f"--{opt}")
                command.append(",".join(map(str, val)))
            else:
                command.append(f"--{opt}")
                command.append(str(val))

    # Add --extra-vars if provided
    if extra_vars:
        try:
            import json
            extra_json = json.dumps(extra_vars)
            command.extend(["--extra-vars", extra_json])
        except Exception as e:
            logger.warning("Failed to serialize extra_vars: %s", e)

    # Append the playbook path
    command.append(playbook_path)

    logger.debug("Executing ansible command: %s", " ".join(command))

    # Execute the command
    try:
        result = subprocess.run(
            command,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            check=True
        )
    except subprocess.CalledProcessError as e:
        error_msg = (
            f"Ansible playbook failed with exit code {e.returncode}\n"
            f"Stdout: {e.stdout}\nStderr: {e.stderr}"
        )
        logger.error(error_msg)
        raise RuntimeError(error_msg) from e

    return result.stdout

def _run_playbook(cli_args, vars_dict, ir_workspace, ir_plugin):
    """
    Runs ansible cli with vars dict

    :param vars_dict: dict, Will be passed as Ansible extra-vars
    :param cli_args: the list  of command line arguments
    :param ir_workspace: An Infrared Workspace object represents the active
     workspace
    :param ir_plugin: An InfraredPlugin object of the current plugin
    :return: ansible results
    """
    # Basic input validation
    if not isinstance(cli_args, (list, tuple)):
        raise TypeError("cli_args must be a list or tuple of strings")
    if not all(isinstance(arg, str) for arg in cli_args):
        raise TypeError("All items in cli_args must be strings")
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dictionary")

    # Build the ansible-playbook command
    command = ["ansible-playbook"] + list(cli_args)

    # Convert vars_dict to --extra-vars string
    if vars_dict:
        extra_parts = []
        for key, value in vars_dict.items():
            # Convert boolean to lowercase
            if isinstance(value, bool):
                val_str = str(value).lower()
            elif isinstance(value, (int, float)):
                val_str = str(value)
            else:
                # Quote the value to preserve spaces
                val_str = f'"{value}"'
            extra_parts.append(f"{key}={val_str}")
        command.extend(["--extra-vars", " ".join(extra_parts)])

    # Attempt to log the command if logger available
    try:
        if ir_plugin and hasattr(ir_plugin, "logger"):
            ir_plugin.logger.debug("Running command: %s", " ".join(command))
    except Exception:
        # Ignore any logging errors
        pass

    try:
        result = subprocess.run(
            command,
            check=True,
            capture_output=True,
            text=True,
        )
        return result.stdout.strip()
    except subprocess.CalledProcessError as exc:
        error_msg = exc.stderr.strip() if exc.stderr else "Ansible playbook failed without stderr."
        raise RuntimeError(f"Ansible playbook execution failed: {error_msg}") from exc
    except OSError as exc:
        raise RuntimeError(f"Failed to execute ansible-playbook: {exc}") from exc

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    :returns: The modified values_dict with values casted to their intended types.
    """
    # Define any concrete type mappings per parser if known.
    # This is optional; generic conversion will be applied otherwise.
    type_map = {
        # Example: 'main': {'count': int, 'verbose': bool},
        # Add additional parser-specific mappings here.
    }

    # Retrieve the mapping for the given parser name, if any.
    parser_map = type_map.get(parser_name, {})

    for key, val in list(values_dict.items()):
        # If the parser has an explicit type for this key, use it.
        if key in parser_map:
            target_type = parser_map[key]
            try:
                if target_type is bool:
                    if isinstance(val, str):
                        values_dict[key] = val.lower() in ('true', '1', 'yes')
                    else:
                        values_dict[key] = bool(val)
                else:
                    values_dict[key] = target_type(val)
            except Exception:
                # If conversion fails, leave the original value unchanged.
                pass
        else:
            # Generic conversion attempts for values that remain strings.
            if isinstance(val, str):
                lower_val = val.lower()
                # Boolean
                if lower_val in ('true', 'false'):
                    values_dict[key] = lower_val == 'true'
                else:
                    # Integer or float
                    try:
                        if '.' in val:
                            values_dict[key] = float(val)
                        else:
                            values_dict[key] = int(val)
                    except ValueError:
                        # Attempt JSON decode
                        try:
                            import json
                            values_dict[key] = json.loads(val)
                        except Exception:
                            # Leave string untouched if all else fails.
                            pass
    return values_dict

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # get the parser object that might contain type information
    parser = getattr(self, "_parsers", {}).get(parser_name)
    if parser is None:
        raise ValueError(f"Parser '{parser_name}' not found")
    # iterate over provided arguments and attempt type conversion
    for key, val in list(values_dict.items()):
        # Determine the target type if available from the parser definition
        tgt_type = None
        if hasattr(parser, "options") and key in parser.options:
            tgt_type = getattr(parser.options[key], "type", None)
        # If we have an explicit type, try to convert
        if tgt_type:
            try:
                values_dict[key] = tgt_type(val)
                continue
            except Exception:
                # fall back to generic conversion
                pass
        # Generic conversion: try bool -> int -> float -> str
        if isinstance(val, str):
            lowered = val.lower()
            if lowered in ("true", "false"):
                values_dict[key] = lowered == "true"
                continue
            # Try integer
            try:
                if val.startswith("0x") or val.startswith("0X"):
                    values_dict[key] = int(val, 16)
                    continue
                values_dict[key] = int(val)
                continue
            except ValueError:
                pass
            # Try float
            try:
                values_dict[key] = float(val)
                continue
            except ValueError:
                pass
        # If value is a comma separated string and no conversion was applied,
        # split it into a list of strings (simple heuristic)
        if isinstance(val, str) and ',' in val:
            try:
                values_dict[key] = [x.strip() for x in val.split(",")]
            except Exception:
                pass
    return values_dict

def _convert_non_cli_args(self, parser_name, values_dict):
    """
    Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Helper to convert string to bool
    def _str_to_bool(val):
        if isinstance(val, bool):
            return val
        if isinstance(val, str):
            truthy = {"1", "true", "yes", "y"}
            falsy = {"0", "false", "no", "n"}
            lower = val.strip().lower()
            if lower in truthy:
                return True
            if lower in falsy:
                return False
        # Fallback: bool() conversion
        return bool(val)

    # Pull the type mapping for this parser, if any.
    # Expected format: {arg_name: type or conversion callable or type name string}
    arg_type_map = getattr(self, "__arg_type_map", {}).get(parser_name, {})

    for arg_name, target in arg_type_map.items():
        if arg_name not in values_dict:
            continue
        raw_val = values_dict[arg_name]
        try:
            if callable(target):
                # Custom conversion function
                converted = target(raw_val)
            elif isinstance(target, type):
                # Built‑in type constructor (int, float, str, etc.)
                converted = target(raw_val)
            elif isinstance(target, str):
                t = target.lower()
                if t == "int":
                    converted = int(raw_val)
                elif t == "float":
                    converted = float(raw_val)
                elif t == "bool":
                    converted = _str_to_bool(raw_val)
                elif t == "list":
                    # Split on commas and strip whitespace
                    converted = [item.strip() for item in str(raw_val).split(",")]
                else:
                    # Unknown type name: leave value untouched
                    converted = raw_val
            else:
                # Unrecognized target: leave as is
                converted = raw_val
            values_dict[arg_name] = converted
        except Exception:
            # If conversion fails, keep the original value
            values_dict[arg_name] = raw_val

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json
    import io

    def _flatten(d, parent_key='', sep='.'):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            elif isinstance(v, list):
                # Flatten list items with index keys
                for idx, item in enumerate(v):
                    if isinstance(item, dict):
                        items.update(_flatten(item, f"{new_key}{sep}{idx}", sep=sep))
                    else:
                        items[f"{new_key}{sep}{idx}"] = item
            else:
                items[new_key] = v
        return items

    flat_spec = {}
    if not plugin_dir:
        return flat_spec
    # Ensure plugin_dir is a string path
    path = str(plugin_dir)
    if not os.path.isdir(path):
        return flat_spec

    # Define possible spec filenames and order of preference
    spec_filenames = ["plugin.json", "plugin.yml", "plugin.yaml"]
    spec_content = None

    for filename in spec_filenames:
        spec_path = os.path.join(path, filename)
        if os.path.isfile(spec_path):
            try:
                with io.open(spec_path, "r", encoding="utf-8") as f:
                    if filename.endswith(".json"):
                        spec_content = json.load(f)
                    else:  # yaml
                        try:
                            import yaml
                        except ImportError:
                            # Cannot read YAML without PyYAML, skip
                            continue
                        spec_content = yaml.safe_load(f)
                break  # stop after first successfully loaded spec
            except Exception:
                # Skip this file if any error occurs
                continue

    if isinstance(spec_content, dict):
        flat_spec = _flatten(spec_content)

    return flat_spec

