        raise ValueError("Path cannot be None.")
    # Normalize both paths
    try:
        norm_path = os.path.abspath(os.path.normpath(path))
        norm_root = os.path.abspath(os.path.normpath(root))
    except Exception as exc:
        raise ValueError(f"Error normalizing paths: {exc}") from exc
    # Ensure root is a prefix of path
    if not norm_path.startswith(norm_root):
        raise ValueError(f"Root '{root}' is not a prefix of path '{path}'.")
    # Strip root and any leading separator
    stripped = norm_path[len(norm_root):]
    if stripped.startswith(os.sep):
        stripped = stripped[len(os.sep):]
    return stripped
